let unsubscribeCalled = false;

/** @param {any} val */
const fakeStore = (val) => ({
	/** @param {(val: any) => void} cb */
	subscribe: (cb) => {
		cb(val);
		return {
			unsubscribe: () => {
				unsubscribeCalled = true;
			}
		};
	}
});

export default test({
	get props() {
		return { foo: fakeStore(1) };
	},
	html: `
