import { expect, test } from '@playwright/test'
import type { Locator, Page } from '@playwright/test'
import path from 'node:path'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return { errors, server }
}

function getTable(page: Page) {
  return page
    .locator('table:visible, .divTable:visible')
    .filter({ has: page.locator('thead th, .thead .th') })
    .filter({ has: page.locator('tbody tr, .tbody .tr') })
    .first()
}

function getHeaderCells(table: Locator) {
  return table.locator('thead th, .thead .th')
}

function getBodyRows(table: Locator) {
  return table.locator('tbody tr, .tbody .tr')
}

async function getFirstBodyRowData(table: Locator) {
  const row = getBodyRows(table).first()
  const firstInput = row
    .locator('input:not([type="checkbox"]):not([type="radio"])')
    .first()

  if ((await firstInput.count()) > 0 && (await firstInput.isVisible())) {
    return firstInput.inputValue()
  }

  const text = await row.textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const table = getTable(page)
    const bodyRows = getBodyRows(table)

    await expect(table).toBeVisible()
    await expect(getHeaderCells(table).first()).toBeVisible()
    await expect(bodyRows.first()).toBeVisible()

    const regenerateButton = page
      .getByRole('button', { name: /^Regenerate Data$/i })
      .first()

    if ((await regenerateButton.count()) > 0) {
      await expect(regenerateButton).toBeVisible()

      const firstRowBefore = await getFirstBodyRowData(table)

      await regenerateButton.click()

      await expect
        .poll(() => getFirstBodyRowData(table))
        .not.toBe(firstRowBefore)
      await expect(bodyRows.first()).toBeVisible()
    }

    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('updates controlled pagination without console errors', async ({
  page,
}) => {
  const { errors, server } = await openExample(page)

  try {
    const table = getTable(page)
    const nextPageButton = page.getByRole('button', {
      name: '>',
      exact: true,
    })
    const pageStatus = page.getByText(/^Page$/).locator('..')

    await expect(getBodyRows(table).first()).toBeVisible()
    await expect(pageStatus).toContainText('1 of 100')
    const firstPageRow = await getFirstBodyRowData(table)

    await nextPageButton.click()

    await expect(pageStatus).toContainText('2 of 100')
    await expect.poll(() => getFirstBodyRowData(table)).not.toBe(firstPageRow)

    const secondPageRow = await getFirstBodyRowData(table)

    await nextPageButton.click()

    await expect(pageStatus).toContainText('3 of 100')
    await expect.poll(() => getFirstBodyRowData(table)).not.toBe(secondPageRow)
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

import { useState } from 'preact/hooks'
import { render } from 'preact'
import { faker } from '@faker-js/faker'
import './index.css'
import {
  columnOrderingFeature,
  columnPinningFeature,
  columnVisibilityFeature,
  createTableHook,
} from '@tanstack/preact-table'
import { makeData } from './makeData'
import type { Person } from './makeData'

// Create table hook with features
const { useAppTable, createAppColumnHelper } = createTableHook({
  features: {
    columnVisibilityFeature,
    columnPinningFeature,
    columnOrderingFeature,
  },
  debugTable: true,
  debugHeaders: true,
  debugColumns: true,
})

// Create column helper
const columnHelper = createAppColumnHelper<Person>()

// Define columns using columnHelper
const columns = columnHelper.columns([
  columnHelper.group({
    header: 'Name',
    footer: (props) => props.column.id,
    columns: columnHelper.columns([
      columnHelper.accessor('firstName', {
        cell: (info) => info.getValue(),
        footer: (props) => props.column.id,
      }),
      columnHelper.accessor((row) => row.lastName, {
        id: 'lastName',
        cell: (info) => info.getValue(),
        header: () => <span>Last Name</span>,
        footer: (props) => props.column.id,
      }),
    ]),
  }),
  columnHelper.group({
    header: 'Info',
    footer: (props) => props.column.id,
    columns: columnHelper.columns([
      columnHelper.accessor('age', {
        header: () => 'Age',
        footer: (props) => props.column.id,
      }),
      columnHelper.group({
        header: 'More Info',
        columns: columnHelper.columns([
          columnHelper.accessor('visits', {
            header: () => <span>Visits</span>,
            footer: (props) => props.column.id,
          }),
          columnHelper.accessor('status', {
            header: 'Status',
            footer: (props) => props.column.id,
          }),
          columnHelper.accessor('progress', {
            header: 'Profile Progress',
            footer: (props) => props.column.id,
          }),
        ]),
      }),
    ]),
  }),
])

function App() {
  const [data, setData] = useState(() => makeData(1_000))

  const refreshData = () => setData(() => makeData(1_000))
  const stressTest = () => setData(() => makeData(1_000_000))

  const table = useAppTable(
    {
      columns,
      data,
      // initialState: { columnPinning: { start: ['firstName'], end: [] } }, // `start`/`end` follow layout direction
      // atoms: { columnPinning: columnPinningAtom }, // preferred: own pinning state with an external atom
      // state: { columnPinning }, // classic controlled state; pair with onColumnPinningChange
      // onColumnPinningChange: setColumnPinning,
      // enableColumnPinning: false, // disable pinning for every column; default true
      debugTable: true,
    },
    (state) => state, // default selector
  )

  const randomizeColumns = () => {
    table.setColumnOrder(
      faker.helpers.shuffle(table.getAllLeafColumns().map((d) => d.id)),
    )
  }

  return (
    <div className="demo-root">
      <div className="column-toggle-panel">
        <div className="column-toggle-panel-header">
          <label>
            <input
              type="checkbox"
              checked={table.getIsAllColumnsVisible()}
              onChange={table.getToggleAllColumnsVisibilityHandler()}
            />{' '}
            Toggle All
          </label>
        </div>
        {table.getAllLeafColumns().map((column) => {
          return (
            <div key={column.id} className="column-toggle-row">
              <label>
                <input
                  type="checkbox"
                  checked={column.getIsVisible()}
                  onChange={column.getToggleVisibilityHandler()}
                />{' '}
                {column.id}
              </label>
            </div>
          )
        })}
      </div>
      <div className="spacer-md" />
      <div className="button-row">
        <button
          onClick={() => refreshData()}
          className="demo-button demo-button-sm"
        >
          Regenerate Data
        </button>
        <button
          onClick={() => stressTest()}
          className="demo-button demo-button-sm"
        >
          Stress Test (1M rows)
        </button>
        <button
          onClick={() => randomizeColumns()}
          className="demo-button demo-button-sm"
        >
          Shuffle Columns
        </button>
      </div>
      <div className="spacer-md" />
      <p className="demo-note">
        This example using the non-split APIs. Columns are just reordered within
        1 table instead of being split into 3 different tables.
      </p>
      <div className="table-row-group">
        <table className="outlined-table">
          <thead>
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} colSpan={header.colSpan}>
                    <div className="nowrap">
                      {header.isPlaceholder ? null : (
                        <table.FlexRender header={header} />
                      )}
                    </div>
                    {!header.isPlaceholder && header.column.getCanPin() && (
                      <div className="pin-actions">
                        {header.column.getIsPinned() !== 'start' ? (
                          <button
                            className="pin-button"
                            onClick={() => {
                              header.column.pin('start')
                            }}
                          >
                            {'<='}
                          </button>
                        ) : null}
                        {header.column.getIsPinned() ? (
                          <button
                            className="pin-button"
                            onClick={() => {
                              header.column.pin(false)
                            }}
                          >
                            X
                          </button>
                        ) : null}
                        {header.column.getIsPinned() !== 'end' ? (
                          <button
                            className="pin-button"
                            onClick={() => {
                              header.column.pin('end')
                            }}
                          >
                            {'=>'}
                          </button>
                        ) : null}
                      </div>
                    )}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {table
              .getRowModel()
              .rows.slice(0, 20)
              .map((row) => {
                return (
                  <tr key={row.id}>
                    {row.getVisibleCells().map((cell) => {
                      return (
                        <td key={cell.id}>
                          <table.FlexRender cell={cell} />
                        </td>
                      )
                    })}
                  </tr>
                )
              })}
          </tbody>
        </table>
      </div>
      <pre data-testid="table-state">
        {JSON.stringify(table.state, null, 2)}
      </pre>
    </div>
  )
}

const rootElement = document.getElementById('root')
if (!rootElement) throw new Error('Failed to find the root element')

render(<App />, rootElement)

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

const TOTAL_ROWS = 5_000

/** Header cell index per column, matching the column order in `src/main.tsx`. */
const COLUMN = {
  rowNumber: 0,
  firstName: 1,
  lastName: 2,
  fullName: 3,
  age: 4,
  visits: 5,
  status: 6,
  progress: 7,
  birthDate: 8,
} as const

const STATUSES = ['complicated', 'relationship', 'single']

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

function headerCell(page: Page, column: keyof typeof COLUMN) {
  return page.locator('thead th').nth(COLUMN[column])
}

function textFilter(page: Page, column: 'firstName' | 'lastName' | 'fullName') {
  return headerCell(page, column).locator('input[type="text"]')
}

function rangeFilter(
  page: Page,
  column: 'age' | 'visits' | 'progress',
  bound: 'Min' | 'Max',
) {
  return headerCell(page, column).getByPlaceholder(bound)
}

function statusFilter(page: Page) {
  return headerCell(page, 'status').locator('select')
}

function dateRangeFilter(page: Page, bound: 'min' | 'max') {
  return headerCell(page, 'birthDate').locator(
    `input[aria-label="birthDate ${bound}"]`,
  )
}

/** The pre-paginated count, so it reflects filtering but not the page window. */
function rowCountLine(page: Page) {
  return page.locator('div').filter({ hasText: /^[\d,]+ Rows$/ })
}

async function readFilteredRowCount(page: Page) {
  const text = await rowCountLine(page).textContent()
  return Number((text ?? '').replace(/\D/g, ''))
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readState(page: Page) {
  const text = await page.getByTestId('table-state').textContent()

  return JSON.parse(text ?? '{}') as {
    columnFilters?: Array<{ id: string; value: unknown }>
    pagination?: { pageIndex: number; pageSize: number }
  }
}

async function readColumnFilters(page: Page) {
  return (await readState(page)).columnFilters ?? []
}

async function expectColumnFilters(
  page: Page,
  expected: Array<{ id: string; value: unknown }>,
) {
  // Every filter control debounces by 500ms, so poll rather than sleeping.
  await expect.poll(() => readColumnFilters(page)).toEqual(expected)
}

async function readBodyColumn(page: Page, column: keyof typeof COLUMN) {
  const cells = await page
    .locator(`tbody tr td:nth-child(${COLUMN[column] + 1})`)
    .allTextContents()

  return cells.map((cell) => cell.trim())
}

async function getFirstBodyRowText(page: Page) {
  const text = await page.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(table.locator('thead th')).toHaveCount(9)
  await expect(page.locator('tbody tr')).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('5,000 Rows')
  await expectColumnFilters(page, [])

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(page.locator('tbody tr').first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(page.locator('tbody tr')).toHaveCount(10)

  expect(errors).toEqual([])
})

test('renders a filter control for every filterable column', async ({
  page,
}) => {
  const errors = await openExample(page)

  // Three text columns, three range columns with a Min and a Max, one select,
  // one date column with a min and a max date input.
  await expect(page.locator('thead input[type="text"]')).toHaveCount(3)
  await expect(page.locator('thead input[type="number"]')).toHaveCount(6)
  await expect(page.locator('thead select')).toHaveCount(1)
  await expect(page.locator('thead input[type="date"]')).toHaveCount(2)

  await expect(textFilter(page, 'firstName')).toHaveAttribute(
    'placeholder',
    'Search...',
  )
  await expect(statusFilter(page).locator('option')).toHaveText([
    'All',
    ...STATUSES,
  ])

  // The row number column has no accessor, so it cannot be filtered.
  await expect(
    headerCell(page, 'rowNumber').locator('input, select'),
  ).toHaveCount(0)

  expect(errors).toEqual([])
})

test('filters by text after the debounce', async ({ page }) => {
  const errors = await openExample(page)

  // A fragment of a name that is actually present, so a match is guaranteed
  // even though the data is regenerated randomly on every load.
  const firstNames = await readBodyColumn(page, 'firstName')
  const fragment = (firstNames[0] ?? '').slice(0, 3).toLowerCase()
  expect(fragment).not.toBe('')

  await textFilter(page, 'firstName').fill(fragment)

  await expectColumnFilters(page, [{ id: 'firstName', value: fragment }])

  const filtered = await readFilteredRowCount(page)
  expect(filtered).toBeGreaterThan(0)
  expect(filtered).toBeLessThan(TOTAL_ROWS)

  for (const name of await readBodyColumn(page, 'firstName')) {
    expect(name.toLowerCase()).toContain(fragment)
  }

  // Emptying a text filter drops it from state rather than keeping a blank.
  await textFilter(page, 'firstName').fill('')

  await expectColumnFilters(page, [])
  await expect(rowCountLine(page)).toHaveText('5,000 Rows')

  expect(errors).toEqual([])
})

test('waits for the debounce before applying the filter', async ({ page }) => {
  const errors = await openExample(page)

  await textFilter(page, 'firstName').fill('zzz')

  // The 500ms debounce has not elapsed, so state is still untouched.
  expect(await readColumnFilters(page)).toEqual([])

  await expectColumnFilters(page, [{ id: 'firstName', value: 'zzz' }])

  expect(errors).toEqual([])
})

test('filters a numeric column by range', async ({ page }) => {
  const errors = await openExample(page)

  await rangeFilter(page, 'age', 'Min').fill('20')

  // An unset bound serialises as null, leaving the range open ended.
  await expectColumnFilters(page, [{ id: 'age', value: ['20', null] }])

  const minOnly = await readFilteredRowCount(page)
  expect(minOnly).toBeLessThan(TOTAL_ROWS)

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeGreaterThanOrEqual(20)
  }

  await rangeFilter(page, 'age', 'Max').fill('25')

  await expectColumnFilters(page, [{ id: 'age', value: ['20', '25'] }])
  expect(await readFilteredRowCount(page)).toBeLessThan(minOnly)

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeGreaterThanOrEqual(20)
    expect(Number(age)).toBeLessThanOrEqual(25)
  }

  // Clearing one bound keeps the filter, with that end left empty.
  await rangeFilter(page, 'age', 'Min').fill('')

  await expectColumnFilters(page, [{ id: 'age', value: ['', '25'] }])

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeLessThanOrEqual(25)
  }

  await rangeFilter(page, 'age', 'Max').fill('')

  await expect.poll(() => readFilteredRowCount(page)).toBe(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('filters a date column by range', async ({ page }) => {
  const errors = await openExample(page)

  // Cells render ISO dates (YYYY-MM-DD), so string order is date order. Use
  // a bound from the visible data so a match is guaranteed despite random rows.
  const dates = (await readBodyColumn(page, 'birthDate')).sort()
  const minDate = dates[Math.floor(dates.length / 2)]!
  expect(minDate).toMatch(/^\d{4}-\d{2}-\d{2}$/)

  await dateRangeFilter(page, 'min').fill(minDate)

  // An unset bound serialises as null, leaving the range open ended.
  await expectColumnFilters(page, [{ id: 'birthDate', value: [minDate, null] }])

  const minOnly = await readFilteredRowCount(page)
  expect(minOnly).toBeGreaterThan(0)
  expect(minOnly).toBeLessThan(TOTAL_ROWS)

  for (const date of await readBodyColumn(page, 'birthDate')) {
    expect(date >= minDate).toBe(true)
  }

  // The largest visible date keeps the range ordered and non-empty.
  const maxDate = dates[dates.length - 1]!
  await dateRangeFilter(page, 'max').fill(maxDate)

  await expectColumnFilters(page, [
    { id: 'birthDate', value: [minDate, maxDate] },
  ])

  for (const date of await readBodyColumn(page, 'birthDate')) {
    expect(date >= minDate).toBe(true)
    expect(date <= maxDate).toBe(true)
  }

  // Clearing both bounds auto-removes the filter entirely.
  await dateRangeFilter(page, 'min').fill('')
  await dateRangeFilter(page, 'max').fill('')

  await expectColumnFilters(page, [])
  await expect(rowCountLine(page)).toHaveText('5,000 Rows')

  expect(errors).toEqual([])
})

test('filters by the status select', async ({ page }) => {
  const errors = await openExample(page)
  const counts: Array<number> = []

  for (const status of STATUSES) {
    await statusFilter(page).selectOption(status)

    await expectColumnFilters(page, [{ id: 'status', value: status }])

    for (const cell of await readBodyColumn(page, 'status')) {
      expect(cell).toBe(status)
    }

    counts.push(await readFilteredRowCount(page))
  }

  // Every row has exactly one of the three statuses, so the parts must make up
  // the whole. This holds no matter what the random data happens to be.
  expect(counts.reduce((total, count) => total + count, 0)).toBe(TOTAL_ROWS)

  // The All option carries an empty value, which removes the filter entirely.
  await statusFilter(page).selectOption('')

  await expectColumnFilters(page, [])
  await expect(rowCountLine(page)).toHaveText('5,000 Rows')

  expect(errors).toEqual([])
})

test('combines filters and returns to the first page', async ({ page }) => {
  const errors = await openExample(page)

  await page.getByRole('button', { name: '>', exact: true }).click()
  await page.getByRole('button', { name: '>', exact: true }).click()
  await expect
    .poll(async () => (await readState(page)).pagination?.pageIndex)
    .toBe(2)

  await statusFilter(page).selectOption('single')

  await expectColumnFilters(page, [{ id: 'status', value: 'single' }])
  // `autoResetPageIndex` defaults to true, so filtering rewinds to page one.
  await expect
    .poll(async () => (await readState(page)).pagination?.pageIndex)
    .toBe(0)

  const statusOnly = await readFilteredRowCount(page)

  await rangeFilter(page, 'age', 'Min').fill('20')

  await expectColumnFilters(page, [
    { id: 'status', value: 'single' },
    { id: 'age', value: ['20', null] },
  ])
  // Filters intersect, so adding one can only narrow the result.
  expect(await readFilteredRowCount(page)).toBeLessThanOrEqual(statusOnly)

  for (const cell of await readBodyColumn(page, 'status')) {
    expect(cell).toBe('single')
  }

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeGreaterThanOrEqual(20)
  }

  expect(errors).toEqual([])
})

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

/** `makeData(1_000)` at the default page size of 10 gives exactly 100 pages. */
const TOTAL_ROWS = 1_000
const PAGE_SIZES = [10, 20, 30, 40, 50]

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

/** `<` is a prefix of `<<`, so every page button match has to be exact. */
function pageButton(page: Page, label: '<<' | '<' | '>' | '>>') {
  return page.getByRole('button', { name: label, exact: true })
}

/** The `{pageIndex + 1} of {pageCount}` readout. */
function pageStatus(page: Page) {
  return page.locator('.controls strong')
}

function goToPageInput(page: Page) {
  return page.getByRole('spinbutton')
}

function pageSizeSelect(page: Page) {
  return page.locator('.controls select')
}

function rowCountLine(page: Page) {
  return page.getByText(/Showing .* Rows/)
}

function bodyRows(page: Page) {
  return page.locator('tbody tr')
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readPagination(page: Page) {
  const text = await page.getByTestId('table-state').textContent()
  const state = JSON.parse(text ?? '{}') as {
    pagination?: { pageIndex: number; pageSize: number }
  }

  return state.pagination
}

async function expectPagination(
  page: Page,
  expected: { pageIndex: number; pageSize: number },
) {
  await expect.poll(() => readPagination(page)).toEqual(expected)
}

async function getFirstBodyRowText(page: Page) {
  const text = await bodyRows(page).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(table.locator('thead th')).toHaveCount(7)
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('Showing 10 of 1,000 Rows')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(bodyRows(page).first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(bodyRows(page)).toHaveCount(10)

  expect(errors).toEqual([])
})

test('disables the first and previous buttons on the first page', async ({
  page,
}) => {
  const errors = await openExample(page)

  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()
  await expect(pageButton(page, '>')).toBeEnabled()
  await expect(pageButton(page, '>>')).toBeEnabled()

  expect(errors).toEqual([])
})

test('advances and rewinds one page at a time', async ({ page }) => {
  const errors = await openExample(page)

  await expect(pageStatus(page)).toHaveText('1 of 100')

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')
  await expectPagination(page, { pageIndex: 1, pageSize: 10 })
  // Reaching page two enables the backwards buttons.
  await expect(pageButton(page, '<<')).toBeEnabled()
  await expect(pageButton(page, '<')).toBeEnabled()
  // The controlled input tracks the page rather than going stale.
  await expect(goToPageInput(page)).toHaveValue('2')

  const secondPageFirstRow = await getFirstBodyRowText(page)

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('3 of 100')

  await pageButton(page, '<').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')
  // Returning to a page shows the same rows, so paging does not reshuffle.
  expect(await getFirstBodyRowText(page)).toBe(secondPageFirstRow)

  // The page window slides but its size and the total do not.
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('Showing 10 of 1,000 Rows')

  expect(errors).toEqual([])
})

test('jumps to the last and first pages', async ({ page }) => {
  const errors = await openExample(page)

  await pageButton(page, '>>').click()
  await expect(pageStatus(page)).toHaveText('100 of 100')
  await expectPagination(page, { pageIndex: 99, pageSize: 10 })
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(pageButton(page, '>')).toBeDisabled()
  await expect(pageButton(page, '>>')).toBeDisabled()
  await expect(pageButton(page, '<<')).toBeEnabled()
  await expect(pageButton(page, '<')).toBeEnabled()

  await pageButton(page, '<<').click()
  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()

  expect(errors).toEqual([])
})

test('goes to an arbitrary page via the Go to page input', async ({ page }) => {
  const errors = await openExample(page)
  const input = goToPageInput(page)

  await expect(input).toHaveAttribute('min', '1')
  await expect(input).toHaveAttribute('max', '100')
  await expect(input).toHaveValue('1')

  await input.fill('42')
  await expect(pageStatus(page)).toHaveText('42 of 100')
  await expectPagination(page, { pageIndex: 41, pageSize: 10 })

  await input.fill('1')
  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expect(pageButton(page, '<')).toBeDisabled()

  // Clearing the field falls back to the first page rather than NaN.
  await input.fill('7')
  await expect(pageStatus(page)).toHaveText('7 of 100')
  await input.fill('')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(pageStatus(page)).toHaveText('1 of 100')

  expect(errors).toEqual([])
})

test('recomputes the page index when the page size changes', async ({
  page,
}) => {
  const errors = await openExample(page)
  const select = pageSizeSelect(page)

  await expect(select.locator('option')).toHaveText([
    ...PAGE_SIZES.map((size) => `Show ${size}`),
    'Show All',
  ])
  await expect(select).toHaveValue('10')

  await select.selectOption('20')
  await expect(bodyRows(page)).toHaveCount(20)
  await expect(pageStatus(page)).toHaveText('1 of 50')
  await expect(rowCountLine(page)).toHaveText('Showing 20 of 1,000 Rows')
  await expectPagination(page, { pageIndex: 0, pageSize: 20 })

  await select.selectOption('50')
  await expect(bodyRows(page)).toHaveCount(50)
  await expect(pageStatus(page)).toHaveText('1 of 20')
  await expect(rowCountLine(page)).toHaveText('Showing 50 of 1,000 Rows')

  // `setPageSize` keeps the row at the top of the page in view by deriving the
  // new page index from the old top row index, rather than resetting to page 1.
  await select.selectOption('10')
  await goToPageInput(page).fill('5')
  await expect(pageStatus(page)).toHaveText('5 of 100')

  // Top row index is 4 * 10 = 40, so 20 rows per page lands on page 3.
  await select.selectOption('20')
  await expect(pageStatus(page)).toHaveText('3 of 50')
  await expectPagination(page, { pageIndex: 2, pageSize: 20 })

  // Top row index is still 2 * 20 = 40, so 50 rows per page lands on page 1.
  await select.selectOption('50')
  await expect(pageStatus(page)).toHaveText('1 of 20')
  await expectPagination(page, { pageIndex: 0, pageSize: 50 })

  expect(errors).toEqual([])
})

test('shows all rows when the All page size is selected', async ({ page }) => {
  const errors = await openExample(page)
  const select = pageSizeSelect(page)

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')

  await select.selectOption('Infinity')

  await expect(select).toHaveValue('Infinity')
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)
  await expect(pageStatus(page)).toHaveText('1 of 1')
  await expect(rowCountLine(page)).toHaveText(
    `Showing ${TOTAL_ROWS.toLocaleString('en-US')} of ${TOTAL_ROWS.toLocaleString('en-US')} Rows`,
  )
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()
  await expect(pageButton(page, '>')).toBeDisabled()
  await expect(pageButton(page, '>>')).toBeDisabled()

  expect(errors).toEqual([])
})

test('resets to the first page when data is regenerated', async ({ page }) => {
  const errors = await openExample(page)

  await goToPageInput(page).fill('5')
  await expect(pageStatus(page)).toHaveText('5 of 100')

  // `autoResetPageIndex` defaults to true, so new data returns to page one.
  await page.getByRole('button', { name: /^Regenerate Data$/i }).click()

  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(rowCountLine(page)).toHaveText(
    `Showing 10 of ${TOTAL_ROWS.toLocaleString('en-US')} Rows`,
  )

  expect(errors).toEqual([])
})

import { useEffect } from 'preact/hooks'

const compactNumber = new Intl.NumberFormat('en-US', {
  notation: 'compact',
  maximumFractionDigits: 1,
})

export const quoteCellLifecycle = {
  created: 0,
  destroyed: 0,
}

export const quoteCellRendererNames = [
  'Market',
  'Name',
  'Symbol',
  'Last',
  'Change',
  'ChangePercent',
  'Bid',
  'BidVolume',
  'Ask',
  'AskVolume',
  'Open',
  'High',
  'Low',
  'Intraday',
] as const

export const quoteComponentNames = [
  'PriceCell',
  'StableMoveCell',
  'UpMoveCell',
  'DownMoveCell',
  'PercentChangeCell',
  'SpreadCell',
  'DepthCell',
  'QuoteAgeCell',
  'SparklineCell',
] as const

export type QuoteCellRendererName = (typeof quoteCellRendererNames)[number]
export type QuoteComponentName = (typeof quoteComponentNames)[number]

const createCounterMap = <Name extends string>(
  names: ReadonlyArray<Name>,
): Record<Name, number> =>
  Object.fromEntries(names.map((name) => [name, 0])) as Record<Name, number>

export const quoteRenderDiagnostics = {
  cellRendererCalls: 0,
  componentRenderCalls: 0,
  cellRendererCallsByName: createCounterMap(quoteCellRendererNames),
  componentRenderCallsByName: createCounterMap(quoteComponentNames),
}

export function recordCellRender<T>(name: QuoteCellRendererName, value: T): T {
  'use no memo'
  // Benchmark instrumentation is intentionally impure and must run per call.
  quoteRenderDiagnostics.cellRendererCalls++
  quoteRenderDiagnostics.cellRendererCallsByName[name]++
  return value
}

function useLifecycleCounter(componentName: QuoteComponentName): void {
  'use no memo'
  // This diagnostic mutation measures component-function invocation itself.
  quoteRenderDiagnostics.componentRenderCalls++
  quoteRenderDiagnostics.componentRenderCallsByName[componentName]++
  useEffect(() => {
    quoteCellLifecycle.created++
    return () => {
      quoteCellLifecycle.destroyed++
    }
  }, [])
}

export function PriceCell(props: {
  price: number
  move: number
  onSelect: () => void
}) {
  useLifecycleCounter('PriceCell')
  return (
    <button
      className={`price-button ${props.move >= 0 ? 'quote-up' : 'quote-down'}`}
      onClick={props.onSelect}
    >
      {props.price.toFixed(2)}
    </button>
  )
}

export function StableMoveCell({ move }: { move: number }) {
  useLifecycleCounter('StableMoveCell')
  return (
    <span className={`move-cell ${move >= 0 ? 'quote-up' : 'quote-down'}`}>
      {formatSigned(move)}
    </span>
  )
}

export function UpMoveCell({ move }: { move: number }) {
  useLifecycleCounter('UpMoveCell')
  return <span className="move-cell quote-up">▲ {formatSigned(move)}</span>
}

export function DownMoveCell({ move }: { move: number }) {
  useLifecycleCounter('DownMoveCell')
  return <span className="move-cell quote-down">▼ {formatSigned(move)}</span>
}

export function PercentChangeCell({ value }: { value: number }) {
  useLifecycleCounter('PercentChangeCell')
  return (
    <span
      className={`percent-change-cell ${value >= 0 ? 'quote-up' : 'quote-down'}`}
    >
      {value >= 0 ? '+' : ''}
      {value.toFixed(2)}%
    </span>
  )
}

export function SpreadCell({ bid, ask }: { bid: number; ask: number }) {
  useLifecycleCounter('SpreadCell')
  const spread = Math.max(0, ask - bid)
  const midpoint = (bid + ask) / 2
  const basisPoints = midpoint === 0 ? 0 : (spread / midpoint) * 10_000

  return (
    <span className={`spread-cell ${basisPoints >= 4 ? 'spread-wide' : ''}`}>
      {spread.toFixed(2)}
      <small>{basisPoints.toFixed(1)} bp</small>
    </span>
  )
}

export function DepthCell(props: { bidSize: number; askSize: number }) {
  useLifecycleCounter('DepthCell')
  const total = props.bidSize + props.askSize
  const bidShare = total === 0 ? 50 : (props.bidSize / total) * 100

  return (
    <div
      className="depth-cell"
      title={`Bid ${props.bidSize} / Ask ${props.askSize}`}
    >
      <span className="depth-bid" style={{ width: `${bidShare}%` }} />
      <span className="depth-ask" style={{ width: `${100 - bidShare}%` }} />
      <span className="depth-values">
        <span>{compactNumber.format(props.bidSize)}</span>
        <span>{compactNumber.format(props.askSize)}</span>
      </span>
    </div>
  )
}

export function QuoteAgeCell({ ageMs }: { ageMs: number }) {
  useLifecycleCounter('QuoteAgeCell')
  const className =
    ageMs >= 1_500
      ? 'quote-age quote-age-stale'
      : ageMs >= 500
        ? 'quote-age quote-age-warm'
        : 'quote-age'

  return (
    <span className={className}>
      {ageMs < 1_000
        ? `${Math.round(ageMs)} ms`
        : `${(ageMs / 1_000).toFixed(1)} s`}
    </span>
  )
}

export function SparklineCell({ values }: { values: ReadonlyArray<number> }) {
  useLifecycleCounter('SparklineCell')
  const rising = (values.at(-1) ?? 0) >= (values[0] ?? 0)
  const { min, max } = findRange(values)
  const range = max - min || 1
  const denominator = Math.max(1, values.length - 1)
  const points = values
    .map((value, index) => {
      const x = (index / denominator) * 100
      const y = 22 - ((value - min) / range) * 20
      return `${x.toFixed(1)},${y.toFixed(1)}`
    })
    .join(' ')

  return (
    <svg
      className={`sparkline ${rising ? 'quote-up' : 'quote-down'}`}
      viewBox="0 0 100 24"
      preserveAspectRatio="none"
    >
      <polyline points={points} />
    </svg>
  )
}

function formatSigned(value: number): string {
  return `${value >= 0 ? '+' : ''}${value.toFixed(2)}`
}

function findRange(values: ReadonlyArray<number>): {
  min: number
  max: number
} {
  const first = values[0] ?? 0
  return values.reduce(
    (range, value) => {
      range.min = Math.min(range.min, value)
      range.max = Math.max(range.max, value)
      return range
    },
    { min: first, max: first },
  )
}

import Box from '@mui/material/Box'
import Checkbox from '@mui/material/Checkbox'
import { Subscribe } from '@tanstack/react-table'
import { useHeaderContext, useTableContext } from '@/hooks/table'

export function SelectAllHeader(): React.ReactNode {
  const table = useTableContext()

  return (
    <Subscribe source={table.atoms.rowSelection}>
      {() => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected()}
          indeterminate={
            !table.getIsAllPageRowsSelected() &&
            table.getIsSomePageRowsSelected()
          }
          onChange={(_, checked) => table.toggleAllPageRowsSelected(checked)}
          slotProps={{ input: { 'aria-label': 'Select all' } }}
          size="small"
        />
      )}
    </Subscribe>
  )
}

export function ResizeHandle(): React.ReactNode {
  const header = useHeaderContext()
  const table = useTableContext()

  if (!header.column.getCanResize()) return null

  return (
    <Subscribe source={table.atoms.columnResizing}>
      {() => (
        <Box
          onDoubleClick={() => header.column.resetSize()}
          onMouseDown={header.getResizeHandler()}
          onTouchStart={header.getResizeHandler()}
          sx={{
            position: 'absolute',
            top: 0,
            right: -6,
            width: 6,
            height: '100%',
            cursor: 'col-resize',
            touchAction: 'none',
            bgcolor: header.column.getIsResizing()
              ? 'primary.main'
              : 'transparent',
            '&:hover': { bgcolor: 'primary.main' },
          }}
        />
      )}
    </Subscribe>
  )
}

import * as React from 'react'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import Box from '@mui/material/Box'

export function toSentenceCase(value: string): string {
  return value
    .replace(/[-_]/g, ' ')
    .replace(/\w\S*/g, (word) => word[0].toUpperCase() + word.slice(1))
}

export function formatDate(value: string): string {
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  }).format(new Date(value))
}

export function toDateInputValue(value: unknown): string {
  if (!value) return ''
  const date = new Date(String(value))
  return Number.isNaN(date.getTime()) ? '' : date.toISOString().slice(0, 10)
}

export function SortableFrame({
  id,
  children,
}: {
  id: string
  children: React.ReactNode
}): React.ReactNode {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id })

  return (
    <Box
      ref={setNodeRef}
      {...attributes}
      {...listeners}
      sx={{
        opacity: isDragging ? 0.6 : 1,
        transform: CSS.Transform.toString(transform),
        transition,
        cursor: 'grab',
        '&:active': {
          cursor: 'grabbing',
        },
      }}
    >
      {children}
    </Box>
  )
}

export function EllipsisText({
  children,
}: {
  children: React.ReactNode
}): React.ReactNode {
  return (
    <Box
      component="span"
      sx={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      }}
    >
      {children}
    </Box>
  )
}

import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'
import type { ClassValue } from 'clsx'

export function cn(...inputs: Array<ClassValue>) {
  return twMerge(clsx(inputs))
}

export function formatDate(
  date: Date | string | number,
  opts: Intl.DateTimeFormatOptions = {},
) {
  return new Intl.DateTimeFormat('en-US', {
    month: opts.month ?? 'long',
    day: opts.day ?? 'numeric',
    year: opts.year ?? 'numeric',
    ...opts,
  }).format(new Date(date))
}

export function toSentenceCase(str: string) {
  return str
    .replace(/_/g, ' ')
    .replace(/([A-Z])/g, ' $1')
    .toLowerCase()
    .replace(/^\w/, (c) => c.toUpperCase())
    .replace(/\s+/g, ' ')
    .trim()
}

import { expect, test } from '@playwright/test'
import type { Locator, Page } from '@playwright/test'
import path from 'node:path'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'

const exampleDir = path.resolve()
const ignoredConsoleErrors = [
  /Cannot update a component .* while rendering a different component/,
]

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    const text = message.text()

    if (
      message.type() === 'error' &&
      !ignoredConsoleErrors.some((pattern) => pattern.test(text))
    ) {
      errors.push(text)
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return { errors, server }
}

async function getFirstBodyRowText(table: Locator) {
  const text = await table.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

