import { defineComponent, ref, watchEffect } from 'vue'
import {
  FlexRender,
  columnFilteringFeature,
  createColumnHelper,
  createExpandedRowModel,
  createFilteredRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  filterFns,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  sortFns,
  tableFeatures,
  useTable,
} from '@tanstack/vue-table'
import { makeData } from './makeData'
import type {
  Cell,
  Column,
  Header,
  HeaderGroup,
  Row,
  Table,
} from '@tanstack/vue-table'
import type { Person } from './makeData'

const features = tableFeatures({
  columnFilteringFeature,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSortingFeature,
  rowSelectionFeature,
  expandedRowModel: createExpandedRowModel(),
  filteredRowModel: createFilteredRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortedRowModel: createSortedRowModel(),
  filterFns,
  sortFns,
})

const columnHelper = createColumnHelper<typeof features, Person>()

const IndeterminateCheckbox = defineComponent({
  name: 'IndeterminateCheckbox',
  props: {
    checked: Boolean,
    indeterminate: Boolean,
    onChange: Function,
    onClick: Function,
    className: String,
  },
  setup(props) {
    const inputRef = ref<HTMLInputElement | null>(null)

    watchEffect(() => {
      if (inputRef.value) {
        inputRef.value.indeterminate = !props.checked && !!props.indeterminate
      }
    })

    return () => (
      <input
        ref={inputRef}
        type="checkbox"
        class={`${props.className ?? ''} sortable-header`}
        checked={props.checked}
        onChange={props.onChange as any}
        onClick={props.onClick as any}
      />
    )
  },
})

function renderFilter(
  column: Column<typeof features, Person>,
  table: Table<typeof features, Person>,
) {
  const firstValue = table
    .getPreFilteredRowModel()
    .flatRows[0]?.getValue(column.id)

  const columnFilterValue = column.getFilterValue()

  if (typeof firstValue === 'number') {
    return (
      <div class="filter-row">
        <input
          type="number"
          value={(columnFilterValue as [number, number] | undefined)?.[0] ?? ''}
          onInput={(event: Event) =>
            column.setFilterValue((old: [number, number] | undefined) => {
              const target = event.currentTarget as HTMLInputElement
              return [target.value, old?.[1]]
            })
          }
          placeholder="Min"
          class="filter-input"
        />
        <input
          type="number"
          value={(columnFilterValue as [number, number] | undefined)?.[1] ?? ''}
          onInput={(event: Event) =>
            column.setFilterValue((old: [number, number] | undefined) => {
              const target = event.currentTarget as HTMLInputElement
              return [old?.[0], target.value]
            })
          }
          placeholder="Max"
          class="filter-input"
        />
      </div>
    )
  }

  return (
    <input
      type="text"
      value={columnFilterValue ?? ''}
      onInput={(event: Event) =>
        column.setFilterValue((event.currentTarget as HTMLInputElement).value)
      }
      placeholder="Search..."
      class="filter-select"
    />
  )
}

export default defineComponent({
