namespace DataStructures.AATree;

/// <summary>
///     A simple self-balancing binary search tree.
/// </summary>
/// <remarks>
///     AA Trees are a form of self-balancing binary search tree named after their inventor
///     Arne Anderson. AA Trees are designed to be simple to understand and implement.
///     This is accomplished by limiting how nodes can be added to the tree.
///     This simplifies rebalancing operations.
///     More information: https://en.wikipedia.org/wiki/AA_tree .
/// </remarks>
/// <typeparam name="TKey">The type of key for the AA tree.</typeparam>
/// <remarks>
///     Initializes a new instance of the <see cref="AaTree{TKey}" /> class with a custom comparer.
/// </remarks>
/// <param name="customComparer">The custom comparer to use to compare keys.</param>
public class AaTree<TKey>(Comparer<TKey> customComparer)
{
    /// <summary>
    ///     The comparer function to use to compare the keys.
    /// </summary>
    private readonly Comparer<TKey> comparer = customComparer;

    /// <summary>
    ///     Initializes a new instance of the <see cref="AaTree{TKey}" /> class.
    /// </summary>
    public AaTree()
        : this(Comparer<TKey>.Default)
    {
    }

    /// <summary>
    ///     Gets the root of the tree.
    /// </summary>
    public AaTreeNode<TKey>? Root { get; private set; }

    /// <summary>
    ///     Gets the number of elements in the tree.
    /// </summary>
    public int Count { get; private set; }

    /// <summary>
    ///     Add a single element to the tree.
    /// </summary>
    /// <param name="key">The element to add to the tree.</param>
    public void Add(TKey key)
    {
        Root = Add(key, Root);
        Count++;
    }

    /// <summary>
    ///     Add multiple elements to the tree.
    /// </summary>
    /// <param name="keys">The elements to add to the tree.</param>
    public void AddRange(IEnumerable<TKey> keys)
    {
        foreach (var key in keys)
        {
            Root = Add(key, Root);
            Count++;
        }
    }

    /// <summary>
    ///     Remove a single element from the tree.
    /// </summary>
    /// <param name="key">Element to remove.</param>
    public void Remove(TKey key)
    {
        if (!Contains(key, Root))
        {
            throw new InvalidOperationException($"{nameof(key)} is not in the tree");
        }

        Root = Remove(key, Root);
        Count--;
    }

    /// <summary>
    ///     Checks if the specified element is in the tree.
    /// </summary>
    /// <param name="key">The element to look for.</param>
    /// <returns>true if the element is in the tree, false otherwise.</returns>
    public bool Contains(TKey key) => Contains(key, Root);

    /// <summary>
    ///     Gets the largest element in the tree. (ie. the element in the right most node).
    /// </summary>
    /// <returns>The largest element in the tree according to the stored comparer.</returns>
    /// <exception cref="InvalidOperationException">Thrown if the tree is empty.</exception>
    public TKey GetMax()
    {
        if (Root is null)
        {
            throw new InvalidOperationException("Tree is empty!");
        }

        return GetMax(Root).Key;
    }

    /// <summary>
    ///     Gets the smallest element in the tree. (ie. the element in the left most node).
    /// </summary>
    /// <returns>The smallest element in the tree according to the stored comparer.</returns>
    /// <throws>InvalidOperationException if the tree is empty.</throws>
    public TKey GetMin()
    {
        if (Root is null)
        {
            throw new InvalidOperationException("Tree is empty!");
        }

        return GetMin(Root).Key;
    }

    /// <summary>
    ///     Gets all the elements in the tree in in-order order.
    /// </summary>
    /// <returns>Sequence of elements in in-order order.</returns>
    public IEnumerable<TKey> GetKeysInOrder()
    {
        var result = new List<TKey>();
        InOrderWalk(Root);
        return result;

        void InOrderWalk(AaTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            InOrderWalk(node.Left);
            result.Add(node.Key);
            InOrderWalk(node.Right);
        }
    }

    /// <summary>
    ///     Gets all the elements in the tree in pre-order order.
    /// </summary>
    /// <returns>Sequence of elements in pre-order order.</returns>
    public IEnumerable<TKey> GetKeysPreOrder()
    {
        var result = new List<TKey>();
        PreOrderWalk(Root);
        return result;

        void PreOrderWalk(AaTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            result.Add(node.Key);
            PreOrderWalk(node.Left);
            PreOrderWalk(node.Right);
        }
    }

    /// <summary>
    ///     Gets all the elements in the tree in post-order order.
    /// </summary>
    /// <returns>Sequence of elements in post-order order.</returns>
    public IEnumerable<TKey> GetKeysPostOrder()
    {
        var result = new List<TKey>();
        PostOrderWalk(Root);
        return result;

        void PostOrderWalk(AaTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            PostOrderWalk(node.Left);
            PostOrderWalk(node.Right);
            result.Add(node.Key);
        }
    }

    /// <summary>
    ///     Recursive function to add an element to the tree.
    /// </summary>
    /// <param name="key">The element to add.</param>
    /// <param name="node">The node to search for a empty spot.</param>
    /// <returns>The node with the added element.</returns>
    /// <exception cref="ArgumentException">Thrown if key is already in the tree.</exception>
    private AaTreeNode<TKey> Add(TKey key, AaTreeNode<TKey>? node)
    {
        if (node is null)
        {
            return new AaTreeNode<TKey>(key, 1);
        }

        if (comparer.Compare(key, node.Key) < 0)
        {
            node.Left = Add(key, node.Left);
        }
        else if (comparer.Compare(key, node.Key) > 0)
        {
            node.Right = Add(key, node.Right);
        }
        else
        {
            throw new ArgumentException($"""Key "{key}" already in tree!""", nameof(key));
        }

        return Split(Skew(node))!;
    }

    /// <summary>
    ///     Recursive function to remove an element from the tree.
    /// </summary>
    /// <param name="key">The element to remove.</param>
    /// <param name="node">The node to search from.</param>
    /// <returns>The node with the specified element removed.</returns>
    private AaTreeNode<TKey>? Remove(TKey key, AaTreeNode<TKey>? node)
    {
        if (node is null)
        {
            return null;
        }

        if (comparer.Compare(key, node.Key) < 0)
        {
            node.Left = Remove(key, node.Left);
        }
        else if (comparer.Compare(key, node.Key) > 0)
        {
            node.Right = Remove(key, node.Right);
        }
        else
        {
            if (node.Left is null && node.Right is null)
            {
                return null;
            }

            if (node.Left is null)
            {
                var successor = GetMin(node.Right!);
                node.Right = Remove(successor.Key, node.Right);
                node.Key = successor.Key;
            }
            else
            {
                var predecessor = GetMax(node.Left);
                node.Left = Remove(predecessor.Key, node.Left);
                node.Key = predecessor.Key;
            }
        }

        node = DecreaseLevel(node);
        node = Skew(node);
        node!.Right = Skew(node.Right);

        if (node.Right is not null)
        {
            node.Right.Right = Skew(node.Right.Right);
        }

        node = Split(node);
        node!.Right = Split(node.Right);
        return node;
    }

    /// <summary>
    ///     Recursive function to check if the element exists in the tree.
    /// </summary>
    /// <param name="key">The element to check for.</param>
    /// <param name="node">The node to search from.</param>
    /// <returns>true if the element exists in the tree, false otherwise.</returns>
    private bool Contains(TKey key, AaTreeNode<TKey>? node) =>
        node is { }
        && comparer.Compare(key, node.Key) is { } v
        && v switch
        {
            { } when v > 0 => Contains(key, node.Right),
            { } when v < 0 => Contains(key, node.Left),
            _ => true,
        };

    /// <summary>
    ///     Recursive to find the maximum/right-most element.
    /// </summary>
    /// <param name="node">The node to traverse from.</param>
    /// <returns>The node with the maximum/right-most element.</returns>
    private AaTreeNode<TKey> GetMax(AaTreeNode<TKey> node)
    {
        while (true)
        {
            if (node.Right is null)
            {
                return node;
            }

            node = node.Right;
        }
    }

    /// <summary>
    ///     Recursive to find the minimum/left-most element.
    /// </summary>
    /// <param name="node">The node to traverse from.</param>
    /// <returns>The node with the minimum/left-most element.</returns>
    private AaTreeNode<TKey> GetMin(AaTreeNode<TKey> node)
    {
        while (true)
        {
            if (node.Left is null)
            {
                return node;
            }

            node = node.Left;
        }
    }

    /// <summary>
    ///     Remove right-horizontal links and replaces them with left-horizontal links.
    ///     Accomplishes this by performing a right rotation.
    /// </summary>
    /// <param name="node">The node to rebalance from.</param>
    /// <returns>The rebalanced node.</returns>
    private AaTreeNode<TKey>? Skew(AaTreeNode<TKey>? node)
    {
        if (node?.Left is null || node.Left.Level != node.Level)
        {
            return node;
        }

        var left = node.Left;
        node.Left = left.Right;
        left.Right = node;
        return left;
    }

    /// <summary>
    ///     Reduces the number of right-horizontal links.
    ///     Accomplishes this by performing a left rotation, and incrementing level.
    /// </summary>
    /// <param name="node">The node to rebalance from.</param>
    /// <returns>The rebalanced node.</returns>
    private AaTreeNode<TKey>? Split(AaTreeNode<TKey>? node)
    {
        if (node?.Right?.Right is null || node.Level != node.Right.Right.Level)
        {
            return node;
        }

        var right = node.Right;
        node.Right = right.Left;
        right.Left = node;
        right.Level++;
        return right;
    }

    /// <summary>
    ///     Decreases the level of node if necessary.
    /// </summary>
    /// <param name="node">The node to decrease level from.</param>
    /// <returns>The node with modified level.</returns>
    private AaTreeNode<TKey> DecreaseLevel(AaTreeNode<TKey> node)
    {
        var newLevel = Math.Min(GetLevel(node.Left), GetLevel(node.Right)) + 1;
        if (newLevel >= node.Level)
        {
            return node;
        }

        node.Level = newLevel;
        if (node.Right is { } && newLevel < node.Right.Level)
        {
            node.Right.Level = newLevel;
        }

        return node;

        static int GetLevel(AaTreeNode<TKey>? x) => x?.Level ?? 0;
    }
}

namespace DataStructures.BTree;

/// <summary>
///     A self-balancing search tree data structure that maintains sorted data
///     and allows searches, sequential access, insertions, and deletions in
///     logarithmic time.
/// </summary>
/// <remarks>
///     A B-Tree is a generalization of a binary search tree in which a node
///     can have more than two children. Unlike self-balancing binary search
///     trees, the B-Tree is optimized for systems that read and write large
///     blocks of data. It is commonly used in databases and file systems.
///
///     Properties of a B-Tree of minimum degree t:
///     1. Every node has at most 2t-1 keys.
///     2. Every node (except root) has at least t-1 keys.
///     3. The root has at least 1 key (if tree is not empty).
///     4. All leaves are at the same level.
///     5. A non-leaf node with k keys has k+1 children.
///
///     Time Complexity:
///     - Search: O(log n)
///     - Insert: O(log n)
///     - Delete: O(log n)
///
///     Space Complexity: O(n)
///
///     See https://en.wikipedia.org/wiki/B-tree for more information.
///     Visualizer: https://www.cs.usfca.edu/~galles/visualization/BTree.html.
/// </remarks>
/// <typeparam name="TKey">Type of key for the tree.</typeparam>
public class BTree<TKey>
{
    /// <summary>
    ///     Gets the number of keys in the tree.
    /// </summary>
    public int Count { get; private set; }

    /// <summary>
    ///     Gets the minimum degree (t) of the B-Tree.
    ///     Each node can contain at most 2t-1 keys and at least t-1 keys (except root).
    /// </summary>
    public int MinimumDegree { get; }

    /// <summary>
    ///     Comparer to use when comparing key values.
    /// </summary>
    private readonly Comparer<TKey> comparer;

    /// <summary>
    ///     Reference to the root node.
    /// </summary>
    private BTreeNode<TKey>? root;

    /// <summary>
    ///     Initializes a new instance of the <see cref="BTree{TKey}"/>
    ///     class with the specified minimum degree.
    /// </summary>
    /// <param name="minimumDegree">
    ///     Minimum degree (t) of the B-Tree. Must be at least 2.
    ///     Each node can contain at most 2t-1 keys.
    /// </param>
    /// <exception cref="ArgumentException">
    ///     Thrown when minimumDegree is less than 2.
    /// </exception>
    public BTree(int minimumDegree = 2)
    {
        if (minimumDegree < 2)
        {
            throw new ArgumentException("Minimum degree must be at least 2.", nameof(minimumDegree));
        }

        MinimumDegree = minimumDegree;
        comparer = Comparer<TKey>.Default;
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="BTree{TKey}"/>
    ///     class with the specified minimum degree and custom comparer.
    /// </summary>
    /// <param name="minimumDegree">
    ///     Minimum degree (t) of the B-Tree. Must be at least 2.
    /// </param>
    /// <param name="customComparer">
    ///     Comparer to use when comparing keys.
    /// </param>
    /// <exception cref="ArgumentException">
    ///     Thrown when minimumDegree is less than 2.
    /// </exception>
    public BTree(int minimumDegree, Comparer<TKey> customComparer)
    {
        if (minimumDegree < 2)
        {
            throw new ArgumentException("Minimum degree must be at least 2.", nameof(minimumDegree));
        }

        MinimumDegree = minimumDegree;
        comparer = customComparer;
    }

    /// <summary>
    ///     Add a single key to the tree.
    /// </summary>
    /// <param name="key">Key value to add.</param>
    public void Add(TKey key)
    {
        if (root is null)
        {
            root = new BTreeNode<TKey>(MinimumDegree, true);
            root.InsertKey(0, key);
            Count++;
            return;
        }

        if (root.IsFull())
        {
            var newRoot = new BTreeNode<TKey>(MinimumDegree, false);
            newRoot.InsertChild(0, root);
            SplitChild(newRoot, 0);
            root = newRoot;
        }

        InsertNonFull(root, key);
        Count++;
    }

    /// <summary>
    ///     Add multiple keys to the tree.
    /// </summary>
    /// <param name="keys">Key values to add.</param>
    public void AddRange(IEnumerable<TKey> keys)
    {
        foreach (var key in keys)
        {
            Add(key);
        }
    }

    /// <summary>
    ///     Remove a key from the tree.
    /// </summary>
    /// <param name="key">Key value to remove.</param>
    /// <exception cref="KeyNotFoundException">
    ///     Thrown when the key is not found in the tree.
    /// </exception>
    public void Remove(TKey key)
    {
        if (root is null)
        {
            throw new KeyNotFoundException($"""Key "{key}" is not in the B-Tree.""");
        }

        Remove(root, key);

        if (root.KeyCount == 0)
        {
            root = root.IsLeaf ? null : root.Children[0];
        }

        Count--;
    }

    /// <summary>
    ///     Check if given key is in the tree.
    /// </summary>
    /// <param name="key">Key value to search for.</param>
    /// <returns>Whether or not the key is in the tree.</returns>
    public bool Contains(TKey key)
    {
        return Search(root, key) is not null;
    }

    /// <summary>
    ///     Get the minimum key in the tree.
    /// </summary>
    /// <returns>Minimum key in tree.</returns>
    /// <exception cref="InvalidOperationException">
    ///     Thrown when the tree is empty.
    /// </exception>
    public TKey GetMin()
    {
        if (root is null)
        {
            throw new InvalidOperationException("B-Tree is empty.");
        }

        return GetMin(root);
    }

    /// <summary>
    ///     Get the maximum key in the tree.
    /// </summary>
    /// <returns>Maximum key in tree.</returns>
    /// <exception cref="InvalidOperationException">
    ///     Thrown when the tree is empty.
    /// </exception>
    public TKey GetMax()
    {
        if (root is null)
        {
            throw new InvalidOperationException("B-Tree is empty.");
        }

        return GetMax(root);
    }

    /// <summary>
    ///     Get keys in order from smallest to largest as defined by the
    ///     comparer.
    /// </summary>
    /// <returns>Keys in tree in order from smallest to largest.</returns>
    public IEnumerable<TKey> GetKeysInOrder()
    {
        List<TKey> result = [];
        InOrderTraversal(root);
        return result;

        void InOrderTraversal(BTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            for (var i = 0; i < node.KeyCount; i++)
            {
                if (!node.IsLeaf)
                {
                    InOrderTraversal(node.Children[i]);
                }

                result.Add(node.Keys[i]);
            }

            if (!node.IsLeaf)
            {
                InOrderTraversal(node.Children[node.KeyCount]);
            }
        }
    }

    /// <summary>
    ///     Get keys in the pre-order order.
    /// </summary>
    /// <returns>Keys in pre-order order.</returns>
    public IEnumerable<TKey> GetKeysPreOrder()
    {
        var result = new List<TKey>();
        PreOrderTraversal(root);
        return result;

        void PreOrderTraversal(BTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            for (var i = 0; i < node.KeyCount; i++)
            {
                result.Add(node.Keys[i]);
            }

            if (!node.IsLeaf)
            {
                for (var i = 0; i <= node.KeyCount; i++)
                {
                    PreOrderTraversal(node.Children[i]);
                }
            }
        }
    }

    /// <summary>
    ///     Get keys in the post-order order.
    /// </summary>
    /// <returns>Keys in the post-order order.</returns>
    public IEnumerable<TKey> GetKeysPostOrder()
    {
        var result = new List<TKey>();
        PostOrderTraversal(root);
        return result;

        void PostOrderTraversal(BTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            if (!node.IsLeaf)
            {
                for (var i = 0; i <= node.KeyCount; i++)
                {
                    PostOrderTraversal(node.Children[i]);
                }
            }

            for (var i = 0; i < node.KeyCount; i++)
            {
                result.Add(node.Keys[i]);
            }
        }
    }

    /// <summary>
    ///     Search for a key in the subtree rooted at the given node.
    /// </summary>
    /// <param name="node">Root of the subtree to search.</param>
    /// <param name="key">Key to search for.</param>
    /// <returns>Node containing the key, or null if not found.</returns>
    private BTreeNode<TKey>? Search(BTreeNode<TKey>? node, TKey key)
    {
        if (node is null)
        {
            return null;
        }

        var i = 0;
        while (i < node.KeyCount && comparer.Compare(key, node.Keys[i]) > 0)
        {
            i++;
        }

        if (i < node.KeyCount && comparer.Compare(key, node.Keys[i]) == 0)
        {
            return node;
        }

        if (node.IsLeaf)
        {
            return null;
        }

        return Search(node.Children[i], key);
    }

    /// <summary>
    ///     Insert a key into a non-full node.
    /// </summary>
    /// <param name="node">Node to insert the key into.</param>
    /// <param name="key">Key to insert.</param>
    /// <exception cref="ArgumentException">
    ///     Thrown when the key already exists in the tree.
    /// </exception>
    private void InsertNonFull(BTreeNode<TKey> node, TKey key)
    {
        if (node.IsLeaf)
        {
            InsertIntoLeaf(node, key);
        }
        else
        {
            InsertIntoNonLeaf(node, key);
        }
    }

    /// <summary>
    ///     Insert a key into a leaf node.
    /// </summary>
    /// <param name="node">Leaf node to insert into.</param>
    /// <param name="key">Key to insert.</param>
    private void InsertIntoLeaf(BTreeNode<TKey> node, TKey key)
    {
        var i = node.KeyCount - 1;

        while (i >= 0 && comparer.Compare(key, node.Keys[i]) < 0)
        {
            node.Keys[i + 1] = node.Keys[i];
            i--;
        }

        if (i >= 0 && comparer.Compare(key, node.Keys[i]) == 0)
        {
            throw new ArgumentException($"""Key "{key}" already exists in B-Tree.""");
        }

        node.Keys[i + 1] = key;
        node.KeyCount++;
    }

    /// <summary>
    ///     Insert a key into a non-leaf node.
    /// </summary>
    /// <param name="node">Non-leaf node to insert into.</param>
    /// <param name="key">Key to insert.</param>
    private void InsertIntoNonLeaf(BTreeNode<TKey> node, TKey key)
    {
        var i = FindInsertionIndex(node, key);

        if (node.Children[i]!.IsFull())
        {
            SplitChild(node, i);

            if (comparer.Compare(key, node.Keys[i]) > 0)
            {
                i++;
            }
        }

        InsertNonFull(node.Children[i]!, key);
    }

    /// <summary>
    ///     Find the index where a key should be inserted in a non-leaf node.
    /// </summary>
    /// <param name="node">Node to search in.</param>
    /// <param name="key">Key to insert.</param>
    /// <returns>Index where the key should be inserted.</returns>
    private int FindInsertionIndex(BTreeNode<TKey> node, TKey key)
    {
        var i = node.KeyCount - 1;

        while (i >= 0 && comparer.Compare(key, node.Keys[i]) < 0)
        {
            i--;
        }

        if (i >= 0 && comparer.Compare(key, node.Keys[i]) == 0)
        {
            throw new ArgumentException($"""Key "{key}" already exists in B-Tree.""");
        }

        return i + 1;
    }

    /// <summary>
    ///     Split a full child of a node.
    /// </summary>
    /// <param name="parent">Parent node.</param>
    /// <param name="childIndex">Index of the child to split.</param>
    private void SplitChild(BTreeNode<TKey> parent, int childIndex)
    {
        var fullChild = parent.Children[childIndex]!;
        var newChild = new BTreeNode<TKey>(MinimumDegree, fullChild.IsLeaf);
        var midIndex = MinimumDegree - 1;

        for (var j = 0; j < MinimumDegree - 1; j++)
        {
            newChild.Keys[j] = fullChild.Keys[j + MinimumDegree];
            newChild.KeyCount++;
        }

        if (!fullChild.IsLeaf)
        {
            for (var j = 0; j < MinimumDegree; j++)
            {
                newChild.Children[j] = fullChild.Children[j + MinimumDegree];
            }
        }

        fullChild.KeyCount = MinimumDegree - 1;

        for (var j = parent.KeyCount; j > childIndex; j--)
        {
            parent.Children[j + 1] = parent.Children[j];
        }

        parent.Children[childIndex + 1] = newChild;

        for (var j = parent.KeyCount - 1; j >= childIndex; j--)
        {
            parent.Keys[j + 1] = parent.Keys[j];
        }

        parent.Keys[childIndex] = fullChild.Keys[midIndex];
        parent.KeyCount++;
    }

    /// <summary>
    ///     Remove a key from the subtree rooted at the given node.
    /// </summary>
    /// <param name="node">Root of the subtree.</param>
    /// <param name="key">Key to remove.</param>
    /// <exception cref="KeyNotFoundException">
    ///     Thrown when the key is not found in the subtree.
    /// </exception>
    private void Remove(BTreeNode<TKey> node, TKey key)
    {
        var idx = FindKey(node, key);

        if (idx < node.KeyCount && comparer.Compare(node.Keys[idx], key) == 0)
        {
            if (node.IsLeaf)
            {
                RemoveFromLeaf(node, idx);
            }
            else
            {
                RemoveFromNonLeaf(node, idx);
            }
        }
        else
        {
            if (node.IsLeaf)
            {
                throw new KeyNotFoundException($"""Key "{key}" is not in the B-Tree.""");
            }

            var isInSubtree = idx == node.KeyCount;

            if (node.Children[idx]!.KeyCount < MinimumDegree)
            {
                Fill(node, idx);
            }

            if (isInSubtree && idx > node.KeyCount)
            {
                Remove(node.Children[idx - 1]!, key);
            }
            else
            {
                Remove(node.Children[idx]!, key);
            }
        }
    }

    /// <summary>
    ///     Find the index of the first key greater than or equal to the given key.
    /// </summary>
    /// <param name="node">Node to search in.</param>
    /// <param name="key">Key to find.</param>
    /// <returns>Index of the first key >= key.</returns>
    private int FindKey(BTreeNode<TKey> node, TKey key)
    {
        var idx = 0;
        while (idx < node.KeyCount && comparer.Compare(node.Keys[idx], key) < 0)
        {
            idx++;
        }

        return idx;
    }

    /// <summary>
    ///     Remove a key from a leaf node.
    /// </summary>
    /// <param name="node">Leaf node to remove from.</param>
    /// <param name="idx">Index of the key to remove.</param>
    private void RemoveFromLeaf(BTreeNode<TKey> node, int idx)
    {
        node.RemoveKey(idx);
    }

    /// <summary>
    ///     Remove a key from a non-leaf node.
    /// </summary>
    /// <param name="node">Non-leaf node to remove from.</param>
    /// <param name="idx">Index of the key to remove.</param>
    private void RemoveFromNonLeaf(BTreeNode<TKey> node, int idx)
    {
        var key = node.Keys[idx];

        if (node.Children[idx]!.KeyCount >= MinimumDegree)
        {
            var predecessor = GetPredecessor(node, idx);
            node.Keys[idx] = predecessor;
            Remove(node.Children[idx]!, predecessor);
        }
        else if (node.Children[idx + 1]!.KeyCount >= MinimumDegree)
        {
            var successor = GetSuccessor(node, idx);
            node.Keys[idx] = successor;
            Remove(node.Children[idx + 1]!, successor);
        }
        else
        {
            Merge(node, idx);
            Remove(node.Children[idx]!, key);
        }
    }

    /// <summary>
    ///     Get the predecessor key of the key at the given index.
    /// </summary>
    /// <param name="node">Node containing the key.</param>
    /// <param name="idx">Index of the key.</param>
    /// <returns>Predecessor key.</returns>
    private TKey GetPredecessor(BTreeNode<TKey> node, int idx)
    {
        var current = node.Children[idx]!;
        while (!current.IsLeaf)
        {
            current = current.Children[current.KeyCount]!;
        }

        return current.Keys[current.KeyCount - 1];
    }

    /// <summary>
    ///     Get the successor key of the key at the given index.
    /// </summary>
    /// <param name="node">Node containing the key.</param>
    /// <param name="idx">Index of the key.</param>
    /// <returns>Successor key.</returns>
    private TKey GetSuccessor(BTreeNode<TKey> node, int idx)
    {
        var current = node.Children[idx + 1]!;
        while (!current.IsLeaf)
        {
            current = current.Children[0]!;
        }

        return current.Keys[0];
    }

    /// <summary>
    ///     Fill a child node that has fewer than minimum degree - 1 keys.
    /// </summary>
    /// <param name="node">Parent node.</param>
    /// <param name="idx">Index of the child to fill.</param>
    private void Fill(BTreeNode<TKey> node, int idx)
    {
        if (idx != 0 && node.Children[idx - 1]!.KeyCount >= MinimumDegree)
        {
            BorrowFromPrevious(node, idx);
        }
        else if (idx != node.KeyCount && node.Children[idx + 1]!.KeyCount >= MinimumDegree)
        {
            BorrowFromNext(node, idx);
        }
        else
        {
            Merge(node, idx != node.KeyCount ? idx : idx - 1);
        }
    }

    /// <summary>
    ///     Borrow a key from the previous sibling.
    /// </summary>
    /// <param name="node">Parent node.</param>
    /// <param name="childIdx">Index of the child that needs a key.</param>
    private void BorrowFromPrevious(BTreeNode<TKey> node, int childIdx)
    {
        var child = node.Children[childIdx]!;
        var sibling = node.Children[childIdx - 1]!;

        for (var i = child.KeyCount - 1; i >= 0; i--)
        {
            child.Keys[i + 1] = child.Keys[i];
        }

        if (!child.IsLeaf)
        {
            for (var i = child.KeyCount; i >= 0; i--)
            {
                child.Children[i + 1] = child.Children[i];
            }
        }

        child.Keys[0] = node.Keys[childIdx - 1];

        if (!child.IsLeaf)
        {
            child.Children[0] = sibling.Children[sibling.KeyCount];
        }

        node.Keys[childIdx - 1] = sibling.Keys[sibling.KeyCount - 1];

        child.KeyCount++;
        sibling.KeyCount--;
    }

    /// <summary>
    ///     Borrow a key from the next sibling.
    /// </summary>
    /// <param name="node">Parent node.</param>
    /// <param name="childIdx">Index of the child that needs a key.</param>
    private void BorrowFromNext(BTreeNode<TKey> node, int childIdx)
    {
        var child = node.Children[childIdx]!;
        var sibling = node.Children[childIdx + 1]!;

        child.Keys[child.KeyCount] = node.Keys[childIdx];

        if (!child.IsLeaf)
        {
            child.Children[child.KeyCount + 1] = sibling.Children[0];
        }

        node.Keys[childIdx] = sibling.Keys[0];

        for (var i = 1; i < sibling.KeyCount; i++)
        {
            sibling.Keys[i - 1] = sibling.Keys[i];
        }

        if (!sibling.IsLeaf)
        {
            for (var i = 1; i <= sibling.KeyCount; i++)
            {
                sibling.Children[i - 1] = sibling.Children[i];
            }
        }

        child.KeyCount++;
        sibling.KeyCount--;
    }

    /// <summary>
    ///     Merge a child with its sibling.
    /// </summary>
    /// <param name="node">Parent node.</param>
    /// <param name="idx">Index of the child to merge.</param>
    private void Merge(BTreeNode<TKey> node, int idx)
    {
        var child = node.Children[idx]!;
        var sibling = node.Children[idx + 1]!;

        child.Keys[MinimumDegree - 1] = node.Keys[idx];

        for (var i = 0; i < sibling.KeyCount; i++)
        {
            child.Keys[i + MinimumDegree] = sibling.Keys[i];
        }

        if (!child.IsLeaf)
        {
            for (var i = 0; i <= sibling.KeyCount; i++)
            {
                child.Children[i + MinimumDegree] = sibling.Children[i];
            }
        }

        for (var i = idx + 1; i < node.KeyCount; i++)
        {
            node.Keys[i - 1] = node.Keys[i];
        }

        for (var i = idx + 2; i <= node.KeyCount; i++)
        {
            node.Children[i - 1] = node.Children[i];
        }

        child.KeyCount += sibling.KeyCount + 1;
        node.KeyCount--;
    }

    /// <summary>
    ///     Get the minimum key in the subtree rooted at the given node.
    /// </summary>
    /// <param name="node">Root of the subtree.</param>
    /// <returns>Minimum key in the subtree.</returns>
    private TKey GetMin(BTreeNode<TKey> node)
    {
        while (!node.IsLeaf)
        {
            node = node.Children[0]!;
        }

        return node.Keys[0];
    }

    /// <summary>
    ///     Get the maximum key in the subtree rooted at the given node.
    /// </summary>
    /// <param name="node">Root of the subtree.</param>
    /// <returns>Maximum key in the subtree.</returns>
    private TKey GetMax(BTreeNode<TKey> node)
    {
        while (!node.IsLeaf)
        {
            node = node.Children[node.KeyCount]!;
        }

        return node.Keys[node.KeyCount - 1];
    }
}

using DataStructures.Hashing.NumberTheory;

namespace DataStructures.Hashing;

/// <summary>
/// Hash table implementation.
/// </summary>
/// <typeparam name="TKey">Type of the key.</typeparam>
/// <typeparam name="TValue">Type of the value.</typeparam>
public class HashTable<TKey, TValue>
{
    private const int DefaultCapacity = 16;
    private const float DefaultLoadFactor = 0.75f;
    private readonly float loadFactor;
    private int capacity;
    private int size;
    private int threshold;

    private Entry<TKey, TValue>?[] entries;

    /// <summary>
    /// Gets the number of elements in the hash table.
    /// </summary>
    public int Count => size;

    /// <summary>
    /// Gets the capacity of the hash table.
    /// </summary>
    public int Capacity => capacity;

    /// <summary>
    /// Gets the load factor of the hash table.
    /// </summary>
    public float LoadFactor => loadFactor;

    /// <summary>
    /// Gets the keys in the hash table.
    /// </summary>
    public IEnumerable<TKey> Keys => entries.Where(e => e != null).Select(e => e!.Key!);

    /// <summary>
    /// Gets the values in the hash table.
    /// </summary>
    public IEnumerable<TValue> Values => entries.Where(e => e != null).Select(e => e!.Value!);

    /// <summary>
    /// Gets or sets the value associated with the specified key.
    /// </summary>
    /// <param name="key">Key to get or set.</param>
    /// <returns>Value associated with the key.</returns>
    public TValue this[TKey? key]
    {
        get
        {
            if (EqualityComparer<TKey>.Default.Equals(key, default))
            {
                throw new ArgumentNullException(nameof(key));
            }

            var entry = FindEntry(key)
                ?? throw new KeyNotFoundException();
            return entry.Value!;
        }

        set
        {
            if (EqualityComparer<TKey>.Default.Equals(key, default))
            {
                throw new ArgumentNullException(nameof(key));
            }

            var entry = FindEntry(key)
                ?? throw new KeyNotFoundException();
            entry.Value = value;
        }
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="HashTable{TKey, TValue}"/> class.
    /// </summary>
    /// <param name="capacity">Initial capacity of the hash table.</param>
    /// <param name="loadFactor">Load factor of the hash table.</param>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="capacity"/> is less than or equal to 0.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="loadFactor"/> is less than or equal to 0.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="loadFactor"/> is greater than 1.</exception>
    /// <remarks>
    /// <paramref name="capacity"/> is rounded to the next prime number.
    /// </remarks>
    /// <see cref="PrimeNumber.NextPrime(int, int, bool)"/>
    /// <see cref="PrimeNumber.IsPrime(int)"/>
    public HashTable(int capacity = DefaultCapacity, float loadFactor = DefaultLoadFactor)
    {
        if (capacity <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(capacity), "Capacity must be greater than 0");
        }

        if (loadFactor <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(loadFactor), "Load factor must be greater than 0");
        }

        if (loadFactor > 1)
        {
            throw new ArgumentOutOfRangeException(nameof(loadFactor), "Load factor must be less than or equal to 1");
        }

        this.capacity = PrimeNumber.NextPrime(capacity);
        this.loadFactor = loadFactor;
        threshold = (int)(this.capacity * loadFactor);
        entries = new Entry<TKey, TValue>[this.capacity];
    }

    /// <summary>
    /// Adds a key-value pair to the hash table.
    /// </summary>
    /// <param name="key">Key to add.</param>
    /// <param name="value">Value to add.</param>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="key"/> is null.</exception>
    /// <exception cref="ArgumentException">Thrown when <paramref name="key"/> already exists in the hash table.</exception>
    /// <remarks>
    /// If the number of elements in the hash table is greater than or equal to the threshold, the hash table is resized.
    /// </remarks>
    public void Add(TKey? key, TValue? value)
    {
        if (EqualityComparer<TKey>.Default.Equals(key, default))
        {
            throw new ArgumentNullException(nameof(key));
        }

        if (size >= threshold)
        {
            Resize();
        }

        var index = GetIndex(key);
        if (entries[index] != null &&
            EqualityComparer<TKey>.Default.Equals(entries[index]!.Key!, key))
        {
            throw new ArgumentException("Key already exists");
        }

        if (EqualityComparer<TValue>.Default.Equals(value, default))
        {
            throw new ArgumentNullException(nameof(value));
        }

        entries[index] = new Entry<TKey, TValue>(key!, value!);
        size++;
    }

    /// <summary>
    /// Removes the key-value pair associated with the specified key.
    /// </summary>
    /// <param name="key">Key to remove.</param>
    /// <returns>True if the key-value pair was removed, false otherwise.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="key"/> is null.</exception>
    /// <remarks>
    /// If the number of elements in the hash table is less than or equal to the threshold divided by 4, the hash table is resized.
    /// </remarks>
    public bool Remove(TKey? key)
    {
        if (EqualityComparer<TKey>.Default.Equals(key, default))
        {
            throw new ArgumentNullException(nameof(key));
        }

        var index = GetIndex(key);
        if (entries[index] == null)
        {
            return false;
        }

        entries[index] = null;
        size--;

        if (size <= threshold / 4)
        {
            Resize();
        }

        return true;
    }

    /// <summary>
    /// Find the index of the entry associated with the specified key.
    /// </summary>
    /// <param name="key">Key to find.</param>
    /// <returns>Index of the entry associated with the key.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="key"/> is null.</exception>
    public int GetIndex(TKey? key)
    {
        if (EqualityComparer<TKey>.Default.Equals(key, default))
        {
            throw new ArgumentNullException(nameof(key));
        }

        var hash = key!.GetHashCode();
        var index = hash % capacity;

        if (index < 0)
        {
            index += capacity;
        }

        return index;
    }

    /// <summary>
    /// Finds the entry associated with the specified key.
    /// </summary>
    /// <param name="key">Key to find.</param>
    /// <returns>Entry associated with the key.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="key"/> is null.</exception>
    /// <remarks>
    /// This method uses <see cref="GetIndex(TKey)"/> internally.
    /// </remarks>
    public Entry<TKey, TValue>? FindEntry(TKey? key)
    {
        if (EqualityComparer<TKey>.Default.Equals(key, default))
        {
            throw new ArgumentNullException(nameof(key));
        }

        var index = GetIndex(key);
        return entries[index];
    }

    /// <summary>
    /// Checks if the hash table contains the specified key.
    /// </summary>
    /// <param name="key">Key to check.</param>
    /// <returns>True if the hash table contains the key, false otherwise.</returns>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="key"/> is null.</exception>
    /// <remarks>
    /// This method uses <see cref="FindEntry(TKey)"/> internally.
    /// </remarks>
    public bool ContainsKey(TKey? key)
    {
        if (EqualityComparer<TKey>.Default.Equals(key, default))
        {
            throw new ArgumentNullException(nameof(key));
        }

        return FindEntry(key) != null;
    }

    /// <summary>
    /// Checks if the hash table contains the specified value.
    /// </summary>
    /// <param name="value">Value to check.</param>
    /// <returns>True if the hash table contains the value, false otherwise.</returns>
    public bool ContainsValue(TValue? value)
    {
        if (EqualityComparer<TValue>.Default.Equals(value, default))
        {
            throw new ArgumentNullException(nameof(value));
        }

        return entries.Any(e => e != null && e.Value!.Equals(value));
    }

    /// <summary>
    /// Clears the hash table.
    /// </summary>
    /// <remarks>
    /// This method resets the capacity of the hash table to the default capacity.
    /// </remarks>
    public void Clear()
    {
        capacity = DefaultCapacity;
        threshold = (int)(capacity * loadFactor);
        entries = new Entry<TKey, TValue>[capacity];
        size = 0;
    }

    /// <summary>
    /// Resizes the hash table.
    /// </summary>
    /// <remarks>
    /// This method doubles or halves the capacity of the hash table and rehashes all the elements.
    /// </remarks>
    public void Resize()
    {
        var newCapacity = size <= threshold / 2
            ? Math.Max(capacity / 2, DefaultCapacity)
            : capacity * 2;
        var newEntries = new Entry<TKey, TValue>[newCapacity];

        foreach (var entry in entries)
        {
            if (entry == null)
            {
                continue;
            }

            var index = entry.Key!.GetHashCode() % newCapacity;
            if (index < 0)
            {
                index += newCapacity;
            }

            newEntries[index] = entry;
        }

        capacity = newCapacity;
        threshold = (int)(capacity * loadFactor);
        entries = newEntries;
    }
}

namespace Utilities.Extensions;

public static class RandomExtensions
{
    /// <summary>
    ///     Returns a random normalized vector of the specified size.
    /// </summary>
    /// <param name="rand">The random number generator.</param>
    /// <param name="size">The size of the vector to return.</param>
    /// <returns>A random normalized vector.</returns>
    public static double[] NextVector(this Random rand, int size)
    {
        var vector = Enumerable.Range(0, size)
            .Select(_ => rand.NextDouble()).ToArray();
        var norm = vector.Magnitude();
        return vector.Select(x => x / norm).ToArray();
    }
}

//The Catalan numbers are a sequence of positive integers that appear in many counting
// problems in combinatorics.
// time complexity: O(n²)
// space complexity: O(n)
//reference: https://brilliant.org/wiki/catalan-numbers/

package dynamic

import "fmt"

var errCatalan = fmt.Errorf("can't have a negative n-th catalan number")

// NthCatalan returns the n-th Catalan Number
// Complexity: O(n²)
func NthCatalanNumber(n int) (int64, error) {
	if n < 0 {
		//doesn't accept negative number
		return 0, errCatalan
	}

	var catalanNumberList []int64
	catalanNumberList = append(catalanNumberList, 1) //first value is 1

	for i := 1; i <= n; i++ {
		catalanNumberList = append(catalanNumberList, 0) //append 0 and calculate

		for j := 0; j < i; j++ {
			catalanNumberList[i] += catalanNumberList[j] * catalanNumberList[i-j-1]
		}
	}

	return catalanNumberList[n], nil
}

