}

func TestDelete(t *testing.T) {
	t.Run("Delete a node with no child", func(t *testing.T) {
		bst := bt.NewBinarySearch[int]()

		bst.Push(90)
		bst.Push(80)
		bst.Push(80)
		bst.Push(100)

		if !bst.Delete(100) {
			t.Errorf("There is a node, whose value is 100")
		}

		if bst.Delete(105) {
			t.Errorf("There is no node, whose value is 105")
		}

		root := bst.Root
		if root.Key() != 90 {
			t.Errorf("Root should have value = 90")
		}

		if root.Left().Key() != 80 {
			t.Errorf("Left child should have value = 80")
		}

		if root.Right().(*bt.BSNode[int]) != nil {
			t.Errorf("Right child should have value = nil")
		}

		if bst.Depth() != 2 {
			t.Errorf("Depth should have value = 2")
		}

		bst.Delete(80)

		if root.Key() != 90 {
			t.Errorf("Root should have value = 90")
		}

		if root.Left().(*bt.BSNode[int]) != nil {
			t.Errorf("Left child should have value = nil")
		}

		if bst.Depth() != 1 {
			t.Errorf("Depth should have value = 1")
		}
	})

	t.Run("Delete a node with one child", func(t *testing.T) {
		bst := bt.NewBinarySearch[int]()

		bst.Push(90)
		bst.Push(80)
		bst.Push(100)
		bst.Push(70)

		if bst.Delete(102) {
			t.Errorf("There is no node, whose value is 102")
		}

		if !bst.Delete(80) {
			t.Errorf("There is a node, whose value is 80")
		}

		root := bst.Root
		if root.Key() != 90 {
			t.Errorf("Root should have value = 90")
		}

		if root.Right().Key() != 100 {
			t.Errorf("Right child should have value = 100")
		}

		if root.Left().Key() != 70 {
			t.Errorf("Left child should have value = 70")
		}

		if bst.Depth() != 2 {
			t.Errorf("Depth should have value = 2")
		}
	})

	t.Run("Delete a node with two children", func(t *testing.T) {
		bst := bt.NewBinarySearch[int]()

		bst.Push(90)
		bst.Push(80)
		bst.Push(100)
		bst.Push(70)
		bst.Push(85)

		if !bst.Delete(80) {
			t.Errorf("There is a node, whose value is 80")
		}

		if bst.Delete(102) {
			t.Errorf("There is no node, whose value is 102")
		}

		root := bst.Root
		if root.Key() != 90 {
			t.Errorf("Root should have value = 90")
		}

		if root.Left().Key() != 85 {
			t.Errorf("Left child should have value = 85")
		}

		if root.Right().Key() != 100 {
			t.Errorf("Right child should have value = 100")
		}

		if bst.Depth() != 3 {
			t.Errorf("Depth should have value = 3")
		}
	})

	t.Run("Random Test", func(t *testing.T) {
		tests := []int{100, 500, 1000, 10_000}
		for _, n := range tests {
			rnd := rand.New(rand.NewSource(time.Now().UnixNano()))
			tree := bt.NewBinarySearch[int]()
			nums := rnd.Perm(n)
			tree.Push(nums...)

			rets := tree.InOrder()
			if !sort.IntsAreSorted(rets) {
				t.Error("Error with Push")
			}

			if res, ok := tree.Min(); !ok || res != rets[0] {
				t.Errorf("Error with Min, get %d, want: %d", res, rets[0])
			}

			if res, ok := tree.Max(); !ok || res != rets[n-1] {
				t.Errorf("Error with Max, get %d, want: %d", res, rets[n-1])
			}

			for i := 0; i < n-1; i++ {
				if ret, ok := tree.Successor(rets[0]); ret != rets[1] || !ok {
					t.Error("Error with Successor")
				}

				if ret, ok := tree.Predecessor(rets[1]); ret != rets[0] || !ok {
					t.Error("Error with Predecessor")
				}

				ok := tree.Delete(nums[i])
				rets = tree.InOrder()
				if !ok || !sort.IntsAreSorted(rets) {
					t.Errorf("Error With Delete")
				}
			}
		}
	})
}

package com.thealgorithms.audiofilters;

/**
 * N-Order IIR Filter Assumes inputs are normalized to [-1, 1]
 *
 * Based on the difference equation from
 * <a href="https://en.wikipedia.org/wiki/Infinite_impulse_response">Wikipedia link</a>
 */
public class IIRFilter {

    private final int order;
    private final double[] coeffsA;
    private final double[] coeffsB;
    private final double[] historyX;
    private final double[] historyY;

    /**
     * Construct an IIR Filter
     *
     * @param order the filter's order
     * @throws IllegalArgumentException if order is zero or less
     */
    public IIRFilter(int order) throws IllegalArgumentException {
        if (order < 1) {
            throw new IllegalArgumentException("order must be greater than zero");
        }

        this.order = order;
        coeffsA = new double[order + 1];
        coeffsB = new double[order + 1];

        // Sane defaults
        coeffsA[0] = 1.0;
        coeffsB[0] = 1.0;

        historyX = new double[order];
        historyY = new double[order];
    }

    /**
     * Set coefficients
     *
     * @param aCoeffs Denominator coefficients
     * @param bCoeffs Numerator coefficients
     * @throws IllegalArgumentException if {@code aCoeffs} or {@code bCoeffs} is
     * not of size {@code order}, or if {@code aCoeffs[0]} is 0.0
     */
    public void setCoeffs(double[] aCoeffs, double[] bCoeffs) throws IllegalArgumentException {
        if (aCoeffs.length != order) {
            throw new IllegalArgumentException("aCoeffs must be of size " + order + ", got " + aCoeffs.length);
        }

        if (aCoeffs[0] == 0.0) {
            throw new IllegalArgumentException("aCoeffs.get(0) must not be zero");
        }

        if (bCoeffs.length != order) {
            throw new IllegalArgumentException("bCoeffs must be of size " + order + ", got " + bCoeffs.length);
        }

        for (int i = 0; i < order; i++) {
            coeffsA[i] = aCoeffs[i];
            coeffsB[i] = bCoeffs[i];
        }
    }

    /**
     * Process a single sample
     *
     * @param sample the sample to process
     * @return the processed sample
     */
    public double process(double sample) {
        double result = 0.0;

        // Process
        for (int i = 1; i <= order; i++) {
            result += (coeffsB[i] * historyX[i - 1] - coeffsA[i] * historyY[i - 1]);
        }
        result = (result + coeffsB[0] * sample) / coeffsA[0];

        // Feedback
        for (int i = order - 1; i > 0; i--) {
            historyX[i] = historyX[i - 1];
            historyY[i] = historyY[i - 1];
        }

        historyX[0] = sample;
        historyY[0] = result;

        return result;
    }
}

package com.thealgorithms.backtracking;

/**
 * Sudoku Solver using Backtracking Algorithm
 * Solves a 9x9 Sudoku puzzle by filling empty cells with valid digits (1-9)
 *
 * @author Navadeep0007
 */
public final class SudokuSolver {

    private static final int GRID_SIZE = 9;
    private static final int SUBGRID_SIZE = 3;
    private static final int EMPTY_CELL = 0;

    private SudokuSolver() {
        // Utility class, prevent instantiation
    }

    /**
     * Solves the Sudoku puzzle using backtracking
     *
     * @param board 9x9 Sudoku board with 0 representing empty cells
     * @return true if puzzle is solved, false otherwise
     */
    public static boolean solveSudoku(int[][] board) {
        if (board == null || board.length != GRID_SIZE) {
            return false;
        }

        for (int row = 0; row < GRID_SIZE; row++) {
            if (board[row].length != GRID_SIZE) {
                return false;
            }
        }

        return solve(board);
    }

    /**
     * Recursive helper method to solve the Sudoku puzzle
     *
     * @param board the Sudoku board
     * @return true if solution is found, false otherwise
     */
    private static boolean solve(int[][] board) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == EMPTY_CELL) {
                    for (int number = 1; number <= GRID_SIZE; number++) {
                        if (isValidPlacement(board, row, col, number)) {
                            board[row][col] = number;

                            if (solve(board)) {
                                return true;
                            }

                            // Backtrack
                            board[row][col] = EMPTY_CELL;
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if placing a number at given position is valid
     *
     * @param board the Sudoku board
     * @param row row index
     * @param col column index
     * @param number number to place (1-9)
     * @return true if placement is valid, false otherwise
     */
    private static boolean isValidPlacement(int[][] board, int row, int col, int number) {
        return !isNumberInRow(board, row, number) && !isNumberInColumn(board, col, number) && !isNumberInSubgrid(board, row, col, number);
    }

    /**
     * Checks if number exists in the given row
     *
     * @param board the Sudoku board
     * @param row row index
     * @param number number to check
     * @return true if number exists in row, false otherwise
     */
    private static boolean isNumberInRow(int[][] board, int row, int number) {
        for (int col = 0; col < GRID_SIZE; col++) {
            if (board[row][col] == number) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if number exists in the given column
     *
     * @param board the Sudoku board
     * @param col column index
     * @param number number to check
     * @return true if number exists in column, false otherwise
     */
    private static boolean isNumberInColumn(int[][] board, int col, int number) {
        for (int row = 0; row < GRID_SIZE; row++) {
            if (board[row][col] == number) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if number exists in the 3x3 subgrid
     *
     * @param board the Sudoku board
     * @param row row index
     * @param col column index
     * @param number number to check
     * @return true if number exists in subgrid, false otherwise
     */
    private static boolean isNumberInSubgrid(int[][] board, int row, int col, int number) {
        int subgridRowStart = row - row % SUBGRID_SIZE;
        int subgridColStart = col - col % SUBGRID_SIZE;

        for (int i = subgridRowStart; i < subgridRowStart + SUBGRID_SIZE; i++) {
            for (int j = subgridColStart; j < subgridColStart + SUBGRID_SIZE; j++) {
                if (board[i][j] == number) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the Sudoku board
     *
     * @param board the Sudoku board
     */
    public static void printBoard(int[][] board) {
        for (int row = 0; row < GRID_SIZE; row++) {
            if (row % SUBGRID_SIZE == 0 && row != 0) {
                System.out.println("-----------");
            }
            for (int col = 0; col < GRID_SIZE; col++) {
                if (col % SUBGRID_SIZE == 0 && col != 0) {
                    System.out.print("|");
                }
                System.out.print(board[row][col]);
            }
            System.out.println();
        }
    }
}

