package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * A utility class to convert Roman numerals into integers.
 *
 * <p>Roman numerals are based on seven symbols given below:
 * <ul>
 *   <li>I = 1</li>
 *   <li>V = 5</li>
 *   <li>X = 10</li>
 *   <li>L = 50</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>If a smaller numeral appears before a larger numeral, it is subtracted.
 * Otherwise, it is added. For example:
 * <pre>
 *   MCMXCIV = 1000 + (1000 - 100) + (100 - 10) + (5 - 1) = 1994
 * </pre>
 */
public final class RomanToInteger {

    private static final Map<Character, Integer> ROMAN_TO_INT = new HashMap<>() {
        {
            put('I', 1);
            put('V', 5);
            put('X', 10);
            put('L', 50);
            put('C', 100);
            put('D', 500);
            put('M', 1000);
        }
    };

    private RomanToInteger() {
    }

    /**
     * Converts a single Roman numeral character to its integer value.
     *
     * @param symbol the Roman numeral character
     * @return the corresponding integer value
     * @throws IllegalArgumentException if the symbol is not a valid Roman numeral
     */
    private static int romanSymbolToInt(final char symbol) {
        return ROMAN_TO_INT.computeIfAbsent(symbol, c -> { throw new IllegalArgumentException("Unknown Roman symbol: " + c); });
    }

    /**
     * Converts a Roman numeral string to its integer equivalent.
     * Steps:
     * <ol>
     *     <li>Iterate over the string from right to left.</li>
     *     <li>For each character, convert it to an integer value.</li>
     *     <li>If the current value is greater than or equal to the max previous value, add it.</li>
     *     <li>Otherwise, subtract it from the sum.</li>
     *     <li>Update the max previous value.</li>
     *     <li>Return the sum.</li>
     * </ol>
     *
     * @param roman the Roman numeral string
     * @return the integer value of the Roman numeral
     * @throws IllegalArgumentException if the input contains invalid Roman characters
     * @throws NullPointerException if the input is {@code null}
     */
    public static int romanToInt(String roman) {
        if (roman == null) {
            throw new NullPointerException("Input cannot be null");
        }

        roman = roman.toUpperCase();
        int sum = 0;
        int maxPrevValue = 0;
        for (int i = roman.length() - 1; i >= 0; i--) {
            int currentValue = romanSymbolToInt(roman.charAt(i));
            if (currentValue >= maxPrevValue) {
                sum += currentValue;
                maxPrevValue = currentValue;
            } else {
                sum -= currentValue;
            }
        }

        return sum;
    }
}

package com.thealgorithms.datastructures.trees;

import com.thealgorithms.datastructures.trees.BinaryTree.Node;
import java.util.HashMap;
import java.util.Map;

/**
 * Approach: Naive Solution: Create root node from first value present in
 * preorder traversal. Look for the index of root node's value in inorder
 * traversal. That will tell total nodes present in left subtree and right
 * subtree. Based on that index create left and right subtree. Complexity: Time:
 * O(n^2) for each node there is iteration to find index in inorder array Space:
 * Stack size = O(height) = O(lg(n))
 * <p>
 * Optimized Solution: Instead of iterating over inorder array to find index of
 * root value, create a hashmap and find out the index of root value.
 * Complexity: Time: O(n) hashmap reduced iteration to find index in inorder
 * array Space: O(n) space taken by hashmap
 */
public final class CreateBinaryTreeFromInorderPreorder {
    private CreateBinaryTreeFromInorderPreorder() {
    }
    public static Node createTree(final Integer[] preorder, final Integer[] inorder) {
        if (preorder == null || inorder == null) {
            return null;
        }
        return createTree(preorder, inorder, 0, 0, inorder.length);
    }

    public static Node createTreeOptimized(final Integer[] preorder, final Integer[] inorder) {
        if (preorder == null || inorder == null) {
            return null;
        }
        Map<Integer, Integer> inorderMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderMap.put(inorder[i], i);
        }
        return createTreeOptimized(preorder, inorderMap, 0, 0, inorder.length);
    }

    private static Node createTree(final Integer[] preorder, final Integer[] inorder, final int preStart, final int inStart, final int size) {
        if (size == 0) {
            return null;
        }

        Node root = new Node(preorder[preStart]);
        int i = inStart;
        while (!preorder[preStart].equals(inorder[i])) {
            i++;
        }
        int leftNodesCount = i - inStart;
        int rightNodesCount = size - leftNodesCount - 1;
        root.left = createTree(preorder, inorder, preStart + 1, inStart, leftNodesCount);
        root.right = createTree(preorder, inorder, preStart + leftNodesCount + 1, i + 1, rightNodesCount);
        return root;
    }

    private static Node createTreeOptimized(final Integer[] preorder, final Map<Integer, Integer> inorderMap, final int preStart, final int inStart, final int size) {
        if (size == 0) {
            return null;
        }

        Node root = new Node(preorder[preStart]);
        int i = inorderMap.get(preorder[preStart]);
        int leftNodesCount = i - inStart;
        int rightNodesCount = size - leftNodesCount - 1;
        root.left = createTreeOptimized(preorder, inorderMap, preStart + 1, inStart, leftNodesCount);
        root.right = createTreeOptimized(preorder, inorderMap, preStart + leftNodesCount + 1, i + 1, rightNodesCount);
        return root;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

/**
 * Given tree is traversed in a 'post-order' way: LEFT -> RIGHT -> ROOT.
 * Below are given the recursive and iterative implementations.
 * <p>
 * Complexities:
 * Recursive: O(n) - time, O(n) - space, where 'n' is the number of nodes in a tree.
 * <p>
 * Iterative: O(n) - time, O(h) - space, where 'n' is the number of nodes in a tree
 * and 'h' is the height of a binary tree.
 * In the worst case 'h' can be O(n) if tree is completely unbalanced, for instance:
 * 5
 *  \
 *   6
 *    \
 *     7
 *      \
 *       8
 *
 * @author Albina Gimaletdinova on 21/02/2023
 */
public final class PostOrderTraversal {
    private PostOrderTraversal() {
    }
    public static List<Integer> recursivePostOrder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        recursivePostOrder(root, result);
        return result;
    }

    public static List<Integer> iterativePostOrder(BinaryTree.Node root) {
        LinkedList<Integer> result = new LinkedList<>();
        if (root == null) {
            return result;
        }

        Deque<BinaryTree.Node> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            BinaryTree.Node node = stack.pop();
            result.addFirst(node.data);
            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }

        return result;
    }

    private static void recursivePostOrder(BinaryTree.Node root, List<Integer> result) {
        if (root == null) {
            return;
        }
        recursivePostOrder(root.left, result);
        recursivePostOrder(root.right, result);
        result.add(root.data);
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Given 2 binary trees.
 * This code checks whether they are the same (structurally identical and have the same values) or
 * not. <p> Example:
 * 1. Binary trees:
 *      1                 1
 *     / \               / \
 *    2   3             2   3
 *   /\   /\           /\   /\
 *  4  5 6  7         4  5 6  7
 * These trees are the same, so the code returns 'true'.
 * <p>
 * 2. Binary trees:
 *      1   1
 *     /     \
 *    2       2
 * These trees are NOT the same (the structure differs), so the code returns 'false'.
 * <p>
 * This solution implements the breadth-first search (BFS) algorithm.
 * For each tree we create a queue and iterate the trees using these queues.
 * On each step we check the nodes for equality, and if the nodes are not the same, return false.
 * Otherwise, add children nodes to the queues and continue traversing the trees.
 * <p>
 * Complexities:
 * O(N) - time, where N is the number of nodes in a binary tree,
 * O(N) - space, where N is the number of nodes in a binary tree.
 *
 * @author Albina Gimaletdinova on 13/01/2023
 */
public final class SameTreesCheck {
    private SameTreesCheck() {
    }
    public static boolean check(BinaryTree.Node p, BinaryTree.Node q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }

        Deque<BinaryTree.Node> q1 = new ArrayDeque<>();
        Deque<BinaryTree.Node> q2 = new ArrayDeque<>();
        q1.add(p);
        q2.add(q);
        while (!q1.isEmpty() && !q2.isEmpty()) {
            BinaryTree.Node first = q1.poll();
            BinaryTree.Node second = q2.poll();
            // check that some node can be null
            // if the check is true: both nodes are null or both nodes are not null
            if (!equalNodes(first, second)) {
                return false;
            }

            if (first != null) {
                if (!equalNodes(first.left, second.left)) {
                    return false;
                }
                if (first.left != null) {
                    q1.add(first.left);
                    q2.add(second.left);
                }

                if (!equalNodes(first.right, second.right)) {
                    return false;
                }
                if (first.right != null) {
                    q1.add(first.right);
                    q2.add(second.right);
                }
            }
        }
        return true;
    }

    private static boolean equalNodes(BinaryTree.Node p, BinaryTree.Node q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }
        return p.data == q.data;
    }
}

package com.thealgorithms.datastructures.trees;

/**
 * 2D Segment Tree (Tree of Trees) implementation.
 * This data structure supports point updates and submatrix sum queries
 * in a 2D grid. It achieves this by nesting 1D Segment Trees within a 1D Segment Tree.
 *
 * Time Complexity:
 * - Build/Initialization: O(N * M)
 * - Point Update: O(log N * log M)
 * - Submatrix Query: O(log N * log M)
 *
 * @see <a href="https://cp-algorithms.com/data_structures/segment_tree.html#2d-segment-tree">2D Segment Tree</a>
 */
public class SegmentTree2D {

    /**
     * Represents a 1D Segment Tree.
     * This is equivalent to your 'Sagara' struct. It manages the columns (X-axis).
     */
    public static class SegmentTree1D {
        private int n;
        private final int[] tree;

        /**
         * Initializes the 1D Segment Tree with the nearest power of 2.
         *
         * @param size The expected number of elements (columns).
         */
        public SegmentTree1D(int size) {
            n = 1;
            while (n < size) {
                n *= 2;
            }
            tree = new int[n * 2];
        }

        /**
         * Recursively updates a point in the 1D tree.
         */
        private void update(int index, int val, int node, int lx, int rx) {
            if (rx - lx == 1) {
                tree[node] = val;
                return;
            }

            int mid = lx + (rx - lx) / 2;
            int leftChild = node * 2 + 1;
            int rightChild = node * 2 + 2;

            if (index < mid) {
                update(index, val, leftChild, lx, mid);
            } else {
                update(index, val, rightChild, mid, rx);
            }

            tree[node] = tree[leftChild] + tree[rightChild];
        }

        /**
         * Public wrapper to update a specific index.
         *
         * @param index The column index to update.
         * @param val   The new value.
         */
        public void update(int index, int val) {
            update(index, val, 0, 0, n);
        }

        /**
         * Retrieves the exact value at a specific leaf node.
         *
         * @param index The column index.
         * @return The value at the given index.
         */
        public int get(int index) {
            return query(index, index + 1, 0, 0, n);
        }

        /**
         * Recursively queries the sum in a 1D range.
         */
        private int query(int l, int r, int node, int lx, int rx) {
            if (lx >= r || rx <= l) {
                return 0; // Out of bounds
            }
            if (lx >= l && rx <= r) {
                return tree[node]; // Fully inside
            }

            int mid = lx + (rx - lx) / 2;
            int leftSum = query(l, r, node * 2 + 1, lx, mid);
            int rightSum = query(l, r, node * 2 + 2, mid, rx);

            return leftSum + rightSum;
        }

        /**
         * Public wrapper to query the sum in the range [l, r).
         *
         * @param l Left boundary (inclusive).
         * @param r Right boundary (exclusive).
         * @return The sum of the range.
         */
        public int query(int l, int r) {
            return query(l, r, 0, 0, n);
        }
    }

    // --- Start of 2D Segment Tree (equivalent to 'Sagara2D') ---

    private int n;
    private final SegmentTree1D[] tree;

    /**
     * Initializes the 2D Segment Tree.
     *
     * @param rows The number of rows in the matrix.
     * @param cols The number of columns in the matrix.
     */
    public SegmentTree2D(int rows, int cols) {
        n = 1;
        while (n < rows) {
            n *= 2;
        }
        tree = new SegmentTree1D[n * 2];
        for (int i = 0; i < n * 2; i++) {
            // Every node in the outer tree is a full 1D tree!
            tree[i] = new SegmentTree1D(cols);
        }
    }

    /**
     * Recursively updates a point in the 2D grid.
     */
    private void update(int row, int col, int val, int node, int lx, int rx) {
        if (rx - lx == 1) {
            tree[node].update(col, val);
            return;
        }

        int mid = lx + (rx - lx) / 2;
        int leftChild = node * 2 + 1;
        int rightChild = node * 2 + 2;

        if (row < mid) {
            update(row, col, val, leftChild, lx, mid);
        } else {
            update(row, col, val, rightChild, mid, rx);
        }

        // The value of the current node's column is the sum of its children's column values
        int leftVal = tree[leftChild].get(col);
        int rightVal = tree[rightChild].get(col);
        tree[node].update(col, leftVal + rightVal);
    }

    /**
     * Public wrapper to update a specific point (row, col).
     *
     * @param row The row index.
     * @param col The column index.
     * @param val The new value.
     */
    public void update(int row, int col, int val) {
        update(row, col, val, 0, 0, n);
    }

    /**
     * Recursively queries the sum in a submatrix.
     */
    private int query(int top, int bottom, int left, int right, int node, int lx, int rx) {
        if (lx >= bottom || rx <= top) {
            return 0; // Out of bounds
        }
        if (lx >= top && rx <= bottom) {
            // Fully inside the row range, so delegate the column query to the 1D tree
            return tree[node].query(left, right);
        }

        int mid = lx + (rx - lx) / 2;
        int leftSum = query(top, bottom, left, right, node * 2 + 1, lx, mid);
        int rightSum = query(top, bottom, left, right, node * 2 + 2, mid, rx);

        return leftSum + rightSum;
    }

    /**
     * Public wrapper to query the sum of a submatrix.
     * Note: boundaries are [top, bottom) and [left, right).
     *
     * @param top    Top row index (inclusive).
     * @param bottom Bottom row index (exclusive).
     * @param left   Left column index (inclusive).
     * @param right  Right column index (exclusive).
     * @return The sum of the submatrix.
     */
    public int query(int top, int bottom, int left, int right) {
        return query(top, bottom, left, right, 0, 0, n);
    }
}

