package com.thealgorithms.dynamicprogramming;
import java.util.HashMap;
import java.util.Map;
/**
 * Collection of Dynamic Programming techniques to solve for the n-th Fibonacci number.
 * <p>
 * This file showcases Top-Down Memoization ({@code fibMemo}), Bottom-Up Tabulation ({@code fibBotUp}),
 * and Space-Optimized Iteration ({@code fibOptimized}).
 * <p>
 * For alternative structural paradigms, mathematical formulas, or verification steps, see:
 * <ul>
 * <li>{@link com.thealgorithms.maths.FibonacciLoop} - Standard Iterative (Loop) approach</li>
 * <li>{@link com.thealgorithms.recursion.FibonacciSeries} - Naive Recursive approach</li>
 * <li>{@link com.thealgorithms.maths.FibonacciJavaStreams} - Functional approach using Java Streams</li>
 * <li>{@link com.thealgorithms.maths.FibonacciNumberGoldenRation} - Closed-form expression using Binet's formula</li>
 * <li>{@link com.thealgorithms.maths.FibonacciNumberCheck} - Utility to check if a given number is a Fibonacci number</li>
 * <li>{@link com.thealgorithms.matrix.matrixexponentiation.Fibonacci} - O(log n) Matrix Exponentiation approach</li>
 * </ul>
 * * @author Varun Upadhyay (https://github.com/varunu28)
 */
public final class Fibonacci {
    private Fibonacci() {
    }

    static final Map<Integer, Integer> CACHE = new HashMap<>();

    /**
     * This method finds the nth fibonacci number using memoization technique
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibMemo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (CACHE.containsKey(n)) {
            return CACHE.get(n);
        }

        int f;

        if (n <= 1) {
            f = n;
        } else {
            f = fibMemo(n - 1) + fibMemo(n - 2);
            CACHE.put(n, f);
        }
        return f;
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBotUp(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        Map<Integer, Integer> fib = new HashMap<>();

        for (int i = 0; i <= n; i++) {
            int f;
            if (i <= 1) {
                f = i;
            } else {
                f = fib.get(i - 1) + fib.get(i - 2);
            }
            fib.put(i, f);
        }

        return fib.get(n);
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * <p>
     * This is optimized version of Fibonacci Program. Without using Hashmap and
     * recursion. It saves both memory and time. Space Complexity will be O(1)
     * Time Complexity will be O(n)
     * <p>
     * Whereas , the above functions will take O(n) Space.
     * @throws IllegalArgumentException if n is negative
     * @author Shoaib Rayeen (https://github.com/shoaibrayeen)
     */
    public static int fibOptimized(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (n == 0) {
            return 0;
        }
        int prev = 0;
        int res = 1;
        int next;
        for (int i = 2; i <= n; i++) {
            next = prev + res;
            prev = res;
            res = next;
        }
        return res;
    }

    /**
     * We have only defined the nth Fibonacci number in terms of the two before it. Now, we will
     * look at Binet's formula to calculate the nth Fibonacci number in constant time. The Fibonacci
     * terms maintain a ratio called golden ratio denoted by Φ, the Greek character pronounced
     * ‘phi'. First, let's look at how the golden ratio is calculated: Φ = ( 1 + √5 )/2
     * = 1.6180339887... Now, let's look at Binet's formula: Sn = Φⁿ–(– Φ⁻ⁿ)/√5 We first calculate
     * the squareRootof5 and phi and store them in variables. Later, we apply Binet's formula to get
     * the required term. Time Complexity will be O(1)
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBinet(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        double squareRootOf5 = Math.sqrt(5);
        double phi = (1 + squareRootOf5) / 2;
        return (int) ((Math.pow(phi, n) - Math.pow(-phi, -n)) / squareRootOf5);
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;
import java.util.Comparator;

/**
 * Computes the minimum search cost of an optimal binary search tree.
 *
 * <p>The algorithm sorts the keys, preserves the corresponding search frequencies, and uses
 * dynamic programming with Knuth's optimization to compute the minimum weighted search cost.
 *
 * <p>Example: if keys = [10, 12] and frequencies = [34, 50], the best tree puts 12 at the root
 * and 10 as its left child. The total cost is 50 * 1 + 34 * 2 = 118.
 *
 * <p>Reference:
 * https://en.wikipedia.org/wiki/Optimal_binary_search_tree
 */
public final class OptimalBinarySearchTree {
    private OptimalBinarySearchTree() {
    }

    /**
     * Computes the minimum weighted search cost for the given keys and search frequencies.
     *
     * @param keys the BST keys
     * @param frequencies the search frequencies associated with the keys
     * @return the minimum search cost
     * @throws IllegalArgumentException if the input is invalid
     */
    public static long findOptimalCost(int[] keys, int[] frequencies) {
        validateInput(keys, frequencies);
        if (keys.length == 0) {
            return 0L;
        }

        int[][] sortedNodes = sortNodes(keys, frequencies);
        int nodeCount = sortedNodes.length;
        long[] prefixSums = buildPrefixSums(sortedNodes);
        long[][] optimalCost = new long[nodeCount][nodeCount];
        int[][] root = new int[nodeCount][nodeCount];

        // Small example:
        // keys        = [10, 12]
        // frequencies = [34, 50]
        // Choosing 12 as the root gives cost 50 * 1 + 34 * 2 = 118,
        // which is better than choosing 10 as the root.

        // Base case: a subtree containing one key has cost equal to its frequency,
        // because that key becomes the root of the subtree and is searched at depth 1.
        for (int index = 0; index < nodeCount; index++) {
            optimalCost[index][index] = sortedNodes[index][1];
            root[index][index] = index;
        }

        // Build solutions for longer and longer key ranges.
        // optimalCost[start][end] stores the minimum search cost for keys in that range.
        for (int length = 2; length <= nodeCount; length++) {
            for (int start = 0; start <= nodeCount - length; start++) {
                int end = start + length - 1;

                // Every key in this range moves one level deeper when we choose a root,
                // so the sum of frequencies is added once to the subtree cost.
                long frequencySum = prefixSums[end + 1] - prefixSums[start];
                optimalCost[start][end] = Long.MAX_VALUE;

                // Knuth's optimization:
                // the best root for [start, end] lies between the best roots of
                // [start, end - 1] and [start + 1, end], so we search only this interval.
                int leftBoundary = root[start][end - 1];
                int rightBoundary = root[start + 1][end];
                for (int currentRoot = leftBoundary; currentRoot <= rightBoundary; currentRoot++) {
                    long leftCost = currentRoot > start ? optimalCost[start][currentRoot - 1] : 0L;
                    long rightCost = currentRoot < end ? optimalCost[currentRoot + 1][end] : 0L;
                    long currentCost = frequencySum + leftCost + rightCost;

                    if (currentCost < optimalCost[start][end]) {
                        optimalCost[start][end] = currentCost;
                        root[start][end] = currentRoot;
                    }
                }
            }
        }

        return optimalCost[0][nodeCount - 1];
    }

    private static void validateInput(int[] keys, int[] frequencies) {
        if (keys == null || frequencies == null) {
            throw new IllegalArgumentException("Keys and frequencies cannot be null");
        }
        if (keys.length != frequencies.length) {
            throw new IllegalArgumentException("Keys and frequencies must have the same length");
        }

        for (int frequency : frequencies) {
            if (frequency < 0) {
                throw new IllegalArgumentException("Frequencies cannot be negative");
            }
        }
    }

    private static int[][] sortNodes(int[] keys, int[] frequencies) {
        int[][] sortedNodes = new int[keys.length][2];
        for (int index = 0; index < keys.length; index++) {
            sortedNodes[index][0] = keys[index];
            sortedNodes[index][1] = frequencies[index];
        }

        // Sort by key so the nodes can be treated as an in-order BST sequence.
        Arrays.sort(sortedNodes, Comparator.comparingInt(node -> node[0]));

        for (int index = 1; index < sortedNodes.length; index++) {
            if (sortedNodes[index - 1][0] == sortedNodes[index][0]) {
                throw new IllegalArgumentException("Keys must be distinct");
            }
        }

        return sortedNodes;
    }

    private static long[] buildPrefixSums(int[][] sortedNodes) {
        long[] prefixSums = new long[sortedNodes.length + 1];
        for (int index = 0; index < sortedNodes.length; index++) {
            // prefixSums[i] holds the total frequency of the first i sorted keys.
            // This lets us get the frequency sum of any range in O(1) time.
            prefixSums[index + 1] = prefixSums[index] + sortedNodes[index][1];
        }
        return prefixSums;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Given a text and wildcard pattern implement a wildcard pattern matching
 * algorithm that finds if wildcard is matched with text. The matching should
 * cover the entire text ?-> matches single characters *-> match the sequence of
 * characters
 *
 * For calculation of Time and Space Complexity. Let N be length of src and M be length of pat
 *
 * Memoization vs Tabulation : https://www.geeksforgeeks.org/tabulation-vs-memoization/
 * Question Link : https://practice.geeksforgeeks.org/problems/wildcard-pattern-matching/1
 */
public final class RegexMatching {
    private RegexMatching() {
    }

    /**
     * Method 1: Determines if the given source string matches the given pattern using a recursive approach.
     * This method directly applies recursion to check if the source string matches the pattern, considering
     * the wildcards '?' and '*'.
     *
     * Time Complexity: O(2^(N+M)), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat) {
        if (src.length() == 0 && pat.length() == 0) {
            return true;
        }
        if (src.length() != 0 && pat.length() == 0) {
            return false;
        }
        if (src.length() == 0 && pat.length() != 0) {
            for (int i = 0; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(0);
        char chp = pat.charAt(0);

        String ros = src.substring(1);
        String rop = pat.substring(1);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(ros, rop);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, rop);
            boolean multiple = regexRecursion(ros, pat);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 2: Determines if the given source string matches the given pattern using recursion.
     * This method utilizes a virtual index for both the source string and the pattern to manage the recursion.
     *
     * Time Complexity: O(2^(N+M)) where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexRecursion(String src, String pat, int svidx, int pvidx) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 3: Determines if the given source string matches the given pattern using top-down dynamic programming (memoization).
     * This method utilizes memoization to store intermediate results, reducing redundant computations and improving efficiency.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the memoization table, plus additional space for the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @param strg A 2D array used for memoization to store the results of subproblems.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat, int svidx, int pvidx, int[][] strg) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        if (strg[svidx][pvidx] != 0) {
            return strg[svidx][pvidx] != 1;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1, strg);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1, strg);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx, strg);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        strg[svidx][pvidx] = ans ? 2 : 1;
        return ans;
    }

    /**
     * Method 4: Determines if the given source string matches the given pattern using bottom-up dynamic programming (tabulation).
     * This method builds a solution iteratively by filling out a table, where each cell represents whether a substring
     * of the source string matches a substring of the pattern.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the table used in the tabulation process.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexBU(String src, String pat) {
        boolean[][] strg = new boolean[src.length() + 1][pat.length() + 1];
        strg[src.length()][pat.length()] = true;
        for (int row = src.length(); row >= 0; row--) {
            for (int col = pat.length() - 1; col >= 0; col--) {
                if (row == src.length()) {
                    if (pat.charAt(col) == '*') {
                        strg[row][col] = strg[row][col + 1];
                    } else {
                        strg[row][col] = false;
                    }
                } else {
                    char chs = src.charAt(row);
                    char chp = pat.charAt(col);

                    boolean ans;
                    if (chs == chp || chp == '?') {
                        ans = strg[row + 1][col + 1];
                    } else if (chp == '*') {
                        boolean blank = strg[row][col + 1];
                        boolean multiple = strg[row + 1][col];
                        ans = blank || multiple;
                    } else {
                        ans = false;
                    }
                    strg[row][col] = ans;
                }
            }
        }
        return strg[0][0];
    }
}

package com.thealgorithms.geometry;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Stack;

/**
 * A Java program that computes the convex hull using the Graham Scan algorithm.
 * The time complexity is O(n) in the best case and O(n log(n)) in the worst case.
 * The space complexity is O(n).
 * This algorithm is applicable only to integral coordinates.
 *
 * References:
 * https://github.com/TheAlgorithms/C-Plus-Plus/blob/master/geometry/graham_scan_algorithm.cpp
 * https://github.com/TheAlgorithms/C-Plus-Plus/blob/master/geometry/graham_scan_functions.hpp
 * https://algs4.cs.princeton.edu/99hull/GrahamScan.java.html
 */
public class GrahamScan {

    private final Stack<Point> hull = new Stack<>();

    public GrahamScan(Point[] points) {
        // Pre-process points: sort by y-coordinate, then by polar order with respect to the first point
        Arrays.sort(points);
        Arrays.sort(points, 1, points.length, points[0].polarOrder());

        hull.push(points[0]);

        // Find the first point not equal to points[0] (firstNonEqualIndex)
        // and the first point not collinear firstNonCollinearIndex with the previous points
        int firstNonEqualIndex;
        for (firstNonEqualIndex = 1; firstNonEqualIndex < points.length; firstNonEqualIndex++) {
            if (!points[0].equals(points[firstNonEqualIndex])) {
                break;
            }
        }

        if (firstNonEqualIndex == points.length) {
            return;
        }

        int firstNonCollinearIndex;
        for (firstNonCollinearIndex = firstNonEqualIndex + 1; firstNonCollinearIndex < points.length; firstNonCollinearIndex++) {
            if (Point.orientation(points[0], points[firstNonEqualIndex], points[firstNonCollinearIndex]) != 0) {
                break;
            }
        }

        hull.push(points[firstNonCollinearIndex - 1]);

        // Process the remaining points and update the hull
        for (int i = firstNonCollinearIndex; i < points.length; i++) {
            Point top = hull.pop();
            while (Point.orientation(hull.peek(), top, points[i]) <= 0) {
                top = hull.pop();
            }
            hull.push(top);
            hull.push(points[i]);
        }
    }

    /**
     * @return An iterable collection of points representing the convex hull.
     */
    public Iterable<Point> hull() {
        return new ArrayList<>(hull);
    }
}

package com.thealgorithms.maths;

/**
 * Multiplies two complex numbers represented as strings in the form "a+bi".
 * Supports negative values and validates input format.
 */
public final class ComplexNumberMultiply {

    private ComplexNumberMultiply() {
    }

    private static int[] parse(String num) {
        if (num == null || !num.matches("-?\\d+\\+-?\\d+i")) {
            throw new IllegalArgumentException("Invalid complex number format: " + num);
        }

        String[] parts = num.split("\\+");
        int real = Integer.parseInt(parts[0]);
        int imaginary = Integer.parseInt(parts[1].replace("i", ""));
        return new int[] {real, imaginary};
    }

    public static String multiply(String num1, String num2) {
        int[] a = parse(num1);
        int[] b = parse(num2);

        int real = a[0] * b[0] - a[1] * b[1];
        int imaginary = a[0] * b[1] + a[1] * b[0];

        return real + "+" + imaginary + "i";
    }
}

package com.thealgorithms.maths;

/**
 * In number theory, an evil number is a non-negative integer that has an even number of 1s in its binary expansion.
 * Non-negative integers that are not evil are called odious numbers.
 *
 * Evil Number Wiki: https://en.wikipedia.org/wiki/Evil_number
 * Odious Number Wiki: https://en.wikipedia.org/wiki/Odious_number
 */
public final class EvilNumber {

    private EvilNumber() {
    }

    // Function to count number of one bits in a number using bitwise operators
    private static int countOneBits(int number) {
        int oneBitCounter = 0;
        while (number > 0) {
            oneBitCounter += number & 1; // increment count if last bit is 1
            number >>= 1; // right shift to next bit
        }
        return oneBitCounter;
    }

    /**
     * Check either {@code number} is an Evil number or Odious number
     *
     * @param number the number
     * @return {@code true} if {@code number} is an Evil number, otherwise false (in case of Odious number)
     */
    public static boolean isEvilNumber(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Negative numbers are not allowed.");
        }

        int noOfOneBits = countOneBits(number);
        return noOfOneBits % 2 == 0;
    }
}

package com.thealgorithms.maths;

/**
 * @author <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>
 * Program description - To find out the inverse square root of the given number
 * <a href="https://en.wikipedia.org/wiki/Fast_inverse_square_root">Wikipedia</a>
 */
public final class FastInverseSqrt {
    private FastInverseSqrt() {
    }
    /**
     * Returns the inverse square root of the given number upto 6 - 8 decimal places.
     * calculates the inverse square root of the given number and returns true if calculated answer
     * matches with given answer else returns false
     *
     * OUTPUT :
     * Input - number = 4522
     * Output: it calculates the inverse squareroot of a number and returns true with it matches the
     * given answer else returns false. 1st approach Time Complexity : O(1) Auxiliary Space Complexity :
     * O(1) Input - number = 4522 Output: it calculates the inverse squareroot of a number and returns
     * true with it matches the given answer else returns false. 2nd approach Time Complexity : O(1)
     * Auxiliary Space Complexity : O(1)
     */
    public static boolean inverseSqrt(float number) {
        float x = number;
        float xhalf = 0.5f * x;
        int i = Float.floatToIntBits(x);
        i = 0x5f3759df - (i >> 1);
        x = Float.intBitsToFloat(i);
        x = x * (1.5f - xhalf * x * x);
        return x == ((float) 1 / (float) Math.sqrt(number));
    }

    /**
     * Returns the inverse square root of the given number upto 14 - 16 decimal places.
     * calculates the inverse square root of the given number and returns true if calculated answer
     * matches with given answer else returns false
     */
    public static boolean inverseSqrt(double number) {
        double x = number;
        double xhalf = 0.5d * x;
        long i = Double.doubleToLongBits(x);
        i = 0x5fe6ec85e7de30daL - (i >> 1);
        x = Double.longBitsToDouble(i);
        for (int it = 0; it < 4; it++) {
            x = x * (1.5d - xhalf * x * x);
        }
        x *= number;
        return x == 1 / Math.sqrt(number);
    }
}

package com.thealgorithms.maths;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Calculates Fibonacci numbers using a functional programming paradigm with Java Streams.
 * <p>
 * This specific implementation uses {@link java.util.stream.Stream#iterate} and reductions to generate terms.
 * <p>
 * For alternative approaches to compute or verify Fibonacci numbers, see:
 * <ul>
 * <li>{@link com.thealgorithms.maths.FibonacciLoop} - Standard Iterative (Loop) approach</li>
 * <li>{@link com.thealgorithms.recursion.FibonacciSeries} - Naive Recursive approach</li>
 * <li>{@link com.thealgorithms.dynamicprogramming.Fibonacci} - Dynamic Programming approaches (Memoization, Bottom-Up, Optimized)</li>
 * <li>{@link com.thealgorithms.maths.FibonacciNumberGoldenRation} - Closed-form expression using Binet's formula</li>
 * <li>{@link com.thealgorithms.maths.FibonacciNumberCheck} - Utility to check if a given number is a Fibonacci number</li>
 * <li>{@link com.thealgorithms.matrix.matrixexponentiation.Fibonacci} - O(log n) Matrix Exponentiation approach</li>
 * </ul>
 * * @author caos321
 * @date 14 October 2021 (Thursday)
 */

public final class FibonacciJavaStreams {
    private FibonacciJavaStreams() {
    }

    public static Optional<BigDecimal> calculate(final BigDecimal index) {
        if (index == null || index.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("Input index cannot be null or negative!");
        }

        if (index.compareTo(BigDecimal.ONE) < 0) {
            return Optional.of(BigDecimal.ZERO);
        }

        if (index.compareTo(BigDecimal.TWO) < 0) {
            return Optional.of(BigDecimal.ONE);
        }

        final List<BigDecimal> results = Stream.iterate(index, x -> x.compareTo(BigDecimal.ZERO) > 0, x -> x.subtract(BigDecimal.ONE))
                                             .reduce(List.of(), (list, current) -> list.isEmpty() || list.size() < 2 ? List.of(BigDecimal.ZERO, BigDecimal.ONE) : List.of(list.get(1), list.get(0).add(list.get(1))), (list1, list2) -> list1);

        return results.isEmpty() ? Optional.empty() : Optional.of(results.get(results.size() - 1));
    }
}

package com.thealgorithms.maths;

/**
 * Fibonacci: 0 1 1 2 3 5 8 13 21 ...
 * This code checks Fibonacci Numbers up to 45th number.
 * Other checks fail because of 'long'-type overflow.
 * <p>
 * This class serves as a <b>verification utility</b> rather than a generation algorithm.
 * <p>
 * For approaches that actively compute the n-th Fibonacci number, see:
 * <ul>
 * <li>{@link com.thealgorithms.maths.FibonacciLoop} - Standard Iterative (Loop) approach</li>
 * <li>{@link com.thealgorithms.recursion.FibonacciSeries} - Naive Recursive approach</li>
 * <li>{@link com.thealgorithms.dynamicprogramming.Fibonacci} - Dynamic Programming approaches (Memoization, Bottom-Up, Optimized)</li>
 * <li>{@link com.thealgorithms.maths.FibonacciJavaStreams} - Functional approach using Java Streams</li>
 * <li>{@link com.thealgorithms.maths.FibonacciNumberGoldenRation} - Closed-form expression using Binet's formula</li>
 * <li>{@link com.thealgorithms.matrix.matrixexponentiation.Fibonacci} - O(log n) Matrix Exponentiation approach</li>
 * </ul>
 */
public final class FibonacciNumberCheck {
    private FibonacciNumberCheck() {
    }
    /**
     * Check if a number is perfect square number
     *
     * @param number the number to be checked
     * @return <tt>true</tt> if {@code number} is a perfect square, otherwise
     *         <tt>false</tt>
     */
    public static boolean isPerfectSquare(long number) {
        long sqrt = (long) Math.sqrt(number);
        return sqrt * sqrt == number;
    }

    /**
     * Check if a number is a Fibonacci number. This is true if and only if at
     * least one of 5x^2+4 or 5x^2-4 is a perfect square
     *
     * @param number the number
     * @return <tt>true</tt> if {@code number} is a Fibonacci number, otherwise
     *         <tt>false</tt>
     * @link https://en.wikipedia.org/wiki/Fibonacci_number#Identification
     */
    public static boolean isFibonacciNumber(long number) {
        long value1 = 5 * number * number + 4;
        long value2 = 5 * number * number - 4;
        return isPerfectSquare(value1) || isPerfectSquare(value2);
    }
}

package com.thealgorithms.maths;

public final class FindMinRecursion {

    private FindMinRecursion() {
    }

    /**
     * Get min of an array using divide and conquer algorithm
     *
     * @param array contains elements
     * @param low the index of the first element
     * @param high the index of the last element
     * @return min of {@code array}
     */

    public static int min(final int[] array, final int low, final int high) {
        if (array.length == 0) {
            throw new IllegalArgumentException("array must be non-empty.");
        }
        if (low == high) {
            return array[low]; // or array[high]
        }

        int mid = (low + high) >>> 1;

        int leftMin = min(array, low, mid); // get min in [low, mid]
        int rightMin = min(array, mid + 1, high); // get min in [mid+1, high]

        return Math.min(leftMin, rightMin);
    }

    /**
     * Get min of an array using recursion algorithm
     *
     * @param array contains elements
     * @return min value of {@code array}
     */
    public static int min(final int[] array) {
        return min(array, 0, array.length - 1);
    }
}

package com.thealgorithms.maths;

import com.thealgorithms.maths.Prime.PrimeCheck;

/**
 * A utility class to check whether a number is a Germain prime or a Safe prime.
 *
 * <p>This class provides methods to:
 * <ul>
 *   <li>Check if a number is a Germain prime</li>
 *   <li>Check if a number is a Safe prime</li>
 * </ul>
 *
 * <p>Definitions:
 * <ul>
 *   <li>A Germain prime is a prime number p such that 2p + 1 is also prime.</li>
 *   <li>A Safe prime is a prime number p such that (p - 1) / 2 is also prime.</li>
 * </ul>
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Safe_and_Sophie_Germain_primes">Wikipedia: Safe and Sophie Germain primes</a>
 */
public final class GermainPrimeAndSafePrime {

    // Private constructor to prevent instantiation
    private GermainPrimeAndSafePrime() {
    }

    /**
     * Checks if a number is a Germain prime.
     *
     * <p>A Germain prime is a prime number p such that 2p + 1 is also prime.
     *
     * @param number the number to check; must be a positive integer
     * @return {@code true} if the number is a Germain prime, {@code false} otherwise
     * @throws IllegalArgumentException if the input number is less than 1
     */
    public static boolean isGermainPrime(int number) {
        if (number < 1) {
            throw new IllegalArgumentException("Input value must be a positive integer. Input value: " + number);
        }
        // A number is a Germain prime if it is prime and 2 * number + 1 is also prime
        return PrimeCheck.isPrime(number) && PrimeCheck.isPrime(2 * number + 1);
    }

    /**
     * Checks if a number is a Safe prime.
     *
     * <p>A Safe prime is a prime number p such that (p - 1) / 2 is also prime.
     *
     * @param number the number to check; must be a positive integer
     * @return {@code true} if the number is a Safe prime, {@code false} otherwise
     * @throws IllegalArgumentException if the input number is less than 1
     */
    public static boolean isSafePrime(int number) {
        if (number < 1) {
            throw new IllegalArgumentException("Input value must be a positive integer. Input value: " + number);
        }
        // A number is a Safe prime if it is prime, (number - 1) is even, and (number - 1) / 2 is prime
        return ((number - 1) % 2 == 0) && PrimeCheck.isPrime(number) && PrimeCheck.isPrime((number - 1) / 2);
    }
}

package com.thealgorithms.maths;

import java.math.BigInteger;

/**
 * This class provides an implementation of the Karatsuba multiplication algorithm.
 *
 * <p>
 * Karatsuba multiplication is a divide-and-conquer algorithm for multiplying two large
 * numbers. It is faster than the classical multiplication algorithm and reduces the
 * time complexity to O(n^1.585) by breaking the multiplication of two n-digit numbers
 * into three multiplications of n/2-digit numbers.
 * </p>
 *
 * <p>
 * The main idea of the Karatsuba algorithm is based on the following observation:
 * </p>
 *
 * <pre>
 * Let x and y be two numbers:
 * x = a * 10^m + b
 * y = c * 10^m + d
 *
 * Then, the product of x and y can be expressed as:
 * x * y = (a * c) * 10^(2*m) + ((a * d) + (b * c)) * 10^m + (b * d)
 * </pre>
 *
 * The Karatsuba algorithm calculates this more efficiently by reducing the number of
 * multiplications from four to three by using the identity:
 *
 * <pre>
 * (a + b)(c + d) = ac + ad + bc + bd
 * </pre>
 *
 * <p>
 * The recursion continues until the numbers are small enough to multiply directly using
 * the traditional method.
 * </p>
 */
public final class KaratsubaMultiplication {

    /**
     * Private constructor to hide the implicit public constructor
     */
    private KaratsubaMultiplication() {
    }

    /**
     * Multiplies two large numbers using the Karatsuba algorithm.
     *
     * <p>
     * This method recursively splits the numbers into smaller parts until they are
     * small enough to be multiplied directly using the traditional method.
     * </p>
     *
     * @param x The first large number to be multiplied (BigInteger).
     * @param y The second large number to be multiplied (BigInteger).
     * @return The product of the two numbers (BigInteger).
     */
    public static BigInteger karatsuba(BigInteger x, BigInteger y) {
        // Base case: when numbers are small enough, use direct multiplication
        // If the number is 4 bits or smaller, switch to the classical method
        if (x.bitLength() <= 4 || y.bitLength() <= 4) {
            return x.multiply(y);
        }

        // Find the maximum bit length of the two numbers
        int n = Math.max(x.bitLength(), y.bitLength());

        // Split the numbers in the middle
        int m = n / 2;

        // High and low parts of the first number x (x = a * 10^m + b)
        BigInteger high1 = x.shiftRight(m); // a = x / 2^m (higher part)
        BigInteger low1 = x.subtract(high1.shiftLeft(m)); // b = x - a * 2^m (lower part)

        // High and low parts of the second number y (y = c * 10^m + d)
        BigInteger high2 = y.shiftRight(m); // c = y / 2^m (higher part)
        BigInteger low2 = y.subtract(high2.shiftLeft(m)); // d = y - c * 2^m (lower part)

        // Recursively calculate three products
        BigInteger z0 = karatsuba(low1, low2); // z0 = b * d (low1 * low2)
        BigInteger z1 = karatsuba(low1.add(high1), low2.add(high2)); // z1 = (a + b) * (c + d)
        BigInteger z2 = karatsuba(high1, high2); // z2 = a * c (high1 * high2)

        // Combine the results using Karatsuba's formula
        // z0 + ((z1 - z2 - z0) << m) + (z2 << 2m)
        return z2
            .shiftLeft(2 * m) // z2 * 10^(2*m)
            .add(z1.subtract(z2).subtract(z0).shiftLeft(m)) // (z1 - z2 - z0) * 10^m
            .add(z0); // z0
    }
}

package com.thealgorithms.maths;

/**
 * In number theory, a lucky number is a natural number in a set which is generated by a certain "sieve".
 * This sieve is similar to the sieve of Eratosthenes that generates the primes,
 * but it eliminates numbers based on their position in the remaining set,
 * instead of their value (or position in the initial set of natural numbers).
 *
 * Wiki: https://en.wikipedia.org/wiki/Lucky_number
 */
public final class LuckyNumber {

    private LuckyNumber() {
    }

    // Common validation method
    private static void validatePositiveNumber(int number) {
        if (number <= 0) {
            throw new IllegalArgumentException("Number must be positive.");
        }
    }

    // Function to check recursively for Lucky Number
    private static boolean isLuckyRecursiveApproach(int n, int counter) {
        // Base case: If counter exceeds n, number is lucky
        if (counter > n) {
            return true;
        }

        // If number is eliminated in this step, it's not lucky
        if (n % counter == 0) {
            return false;
        }

        // Calculate new position after removing every counter-th number
        int newNumber = n - (n / counter);

        // Recursive call for next round
        return isLuckyRecursiveApproach(newNumber, counter + 1);
    }

    /**
     * Check if {@code number} is a Lucky number or not using recursive approach
     *
     * @param number the number
     * @return {@code true} if {@code number} is a Lucky number, otherwise false
     */
    public static boolean isLuckyNumber(int number) {
        validatePositiveNumber(number);
        int counterStarting = 2;
        return isLuckyRecursiveApproach(number, counterStarting);
    }

    /**
     * Check if {@code number} is a Lucky number or not using iterative approach
     *
     * @param number the number
     * @return {@code true} if {@code number} is a Lucky number, otherwise false
     */
    public static boolean isLucky(int number) {
        validatePositiveNumber(number);

        int counter = 2; // Position starts from 2 (since first elimination happens at 2)
        int position = number; // The position of the number in the sequence

        while (counter <= position) {
            if (position % counter == 0) {
                return false;
            } // Number is eliminated

            // Update the position of n after removing every counter-th number
            position = position - (position / counter);
            counter++;
        }

        return true; // Survives all eliminations → Lucky Number
    }
}

package com.thealgorithms.maths;

/**
 * The trinomial triangle is a variation of Pascal’s triangle. The difference
 * between the two is that an entry in the trinomial triangle is the sum of the
 * three (rather than the two in Pasacal’s triangle) entries above it
 *
 * Example Input: n = 4 Output 1 1 1 1 1 2 3 2 1 1 3 6 7 6 3 1
 */
public final class TrinomialTriangle {
    private TrinomialTriangle() {
    }

    public static int trinomialValue(int n, int k) {
        if (n == 0 && k == 0) {
            return 1;
        }

        if (k < -n || k > n) {
            return 0;
        }

        return (trinomialValue(n - 1, k - 1) + trinomialValue(n - 1, k) + trinomialValue(n - 1, k + 1));
    }

    public static void printTrinomial(int n) {
        for (int i = 0; i < n; i++) {
            for (int j = -i; j <= 0; j++) {
                System.out.print(trinomialValue(i, j) + " ");
            }

            for (int j = 1; j <= i; j++) {
                System.out.print(trinomialValue(i, j) + " ");
            }

            System.out.println();
        }
    }

    public static void main(String[] argc) {
        int n = 6;
        printTrinomial(n);
    }
}

