package com.thealgorithms.others;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/**
 * Creates a random password from ASCII letters Given password length bounds
 *
 * @author AKS1996
 * @date 2017.10.25
 */
final class PasswordGen {
    private static final String UPPERCASE_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String LOWERCASE_LETTERS = "abcdefghijklmnopqrstuvwxyz";
    private static final String DIGITS = "0123456789";
    private static final String SPECIAL_CHARACTERS = "!@#$%^&*(){}?";
    private static final String ALL_CHARACTERS = UPPERCASE_LETTERS + LOWERCASE_LETTERS + DIGITS + SPECIAL_CHARACTERS;

    private PasswordGen() {
    }

    /**
     * Generates a random password with a length between minLength and maxLength.
     *
     * @param minLength The minimum length of the password.
     * @param maxLength The maximum length of the password.
     * @return A randomly generated password.
     * @throws IllegalArgumentException if minLength is greater than maxLength or if either is non-positive.
     */
    public static String generatePassword(int minLength, int maxLength) {
        if (minLength > maxLength || minLength <= 0 || maxLength <= 0) {
            throw new IllegalArgumentException("Incorrect length parameters: minLength must be <= maxLength and both must be > 0");
        }

        Random random = new Random();

        List<Character> letters = new ArrayList<>();
        for (char c : ALL_CHARACTERS.toCharArray()) {
            letters.add(c);
        }

        // Inbuilt method to randomly shuffle the elements of a list
        Collections.shuffle(letters);
        StringBuilder password = new StringBuilder();

        // Note that size of the password is also random
        for (int i = random.nextInt(maxLength - minLength) + minLength; i > 0; --i) {
            password.append(ALL_CHARACTERS.charAt(random.nextInt(ALL_CHARACTERS.length())));
        }

        return password.toString();
    }
}

package com.thealgorithms.physics;

/**
 * Ground to ground projectile motion calculator
 *
 * Ground to ground projectile motion is when a projectile's trajectory
 * starts at the ground, reaches the apex, then falls back on the ground.
 *
 * @author [Yash Rajput](https://github.com/the-yash-rajput)
 */
public final class GroundToGroundProjectileMotion {

    private GroundToGroundProjectileMotion() {
        throw new AssertionError("No instances.");
    }

    /** Standard gravity constant (m/s^2) */
    private static final double GRAVITY = 9.80665;

    /**
     * Convert degrees to radians
     *
     * @param degrees Angle in degrees
     * @return Angle in radians
     */
    private static double degreesToRadians(double degrees) {
        return degrees * (Math.PI / 180.0);
    }

    /**
     * Calculate the time of flight
     *
     * @param initialVelocity The starting velocity of the projectile (m/s)
     * @param angle The angle that the projectile is launched at in degrees
     * @return The time that the projectile is in the air for (seconds)
     */
    public static double timeOfFlight(double initialVelocity, double angle) {
        return timeOfFlight(initialVelocity, angle, GRAVITY);
    }

    /**
     * Calculate the time of flight with custom gravity
     *
     * @param initialVelocity The starting velocity of the projectile (m/s)
     * @param angle The angle that the projectile is launched at in degrees
     * @param gravity The value used for the gravity constant (m/s^2)
     * @return The time that the projectile is in the air for (seconds)
     */
    public static double timeOfFlight(double initialVelocity, double angle, double gravity) {
        double viy = initialVelocity * Math.sin(degreesToRadians(angle));
        return 2.0 * viy / gravity;
    }

    /**
     * Calculate the horizontal distance that the projectile travels
     *
     * @param initialVelocity The starting velocity of the projectile (m/s)
     * @param angle The angle that the projectile is launched at in degrees
     * @param time The time that the projectile is in the air (seconds)
     * @return Horizontal distance that the projectile travels (meters)
     */
    public static double horizontalRange(double initialVelocity, double angle, double time) {
        double vix = initialVelocity * Math.cos(degreesToRadians(angle));
        return vix * time;
    }

    /**
     * Calculate the max height of the projectile
     *
     * @param initialVelocity The starting velocity of the projectile (m/s)
     * @param angle The angle that the projectile is launched at in degrees
     * @return The max height that the projectile reaches (meters)
     */
    public static double maxHeight(double initialVelocity, double angle) {
        return maxHeight(initialVelocity, angle, GRAVITY);
    }

    /**
     * Calculate the max height of the projectile with custom gravity
     *
     * @param initialVelocity The starting velocity of the projectile (m/s)
     * @param angle The angle that the projectile is launched at in degrees
     * @param gravity The value used for the gravity constant (m/s^2)
     * @return The max height that the projectile reaches (meters)
     */
    public static double maxHeight(double initialVelocity, double angle, double gravity) {
        double viy = initialVelocity * Math.sin(degreesToRadians(angle));
        return Math.pow(viy, 2) / (2.0 * gravity);
    }
}

package com.thealgorithms.physics;

/**
 *
 * This implementation calculates the flight path of a projectile launched from any INITIAL HEIGHT.
 * It is a more flexible version of the ground-to-ground model.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Projectile_motion">Wikipedia - Projectile Motion</a>
 * @author [Priyanshu Kumar Singh](https://github.com/Priyanshu1303d)
 */
public final class ProjectileMotion {

    private ProjectileMotion() {
    }

    /** Standard Earth gravity constant*/
    private static final double GRAVITY = 9.80665;

    /**
     * A simple container for the results of a projectile motion calculation.
     */
    public static final class Result {
        private final double timeOfFlight;
        private final double horizontalRange;
        private final double maxHeight;

        public Result(double timeOfFlight, double horizontalRange, double maxHeight) {
            this.timeOfFlight = timeOfFlight;
            this.horizontalRange = horizontalRange;
            this.maxHeight = maxHeight;
        }

        /** @return The total time the projectile is in the air (seconds). */
        public double getTimeOfFlight() {
            return timeOfFlight;
        }

        /** @return The total horizontal distance traveled (meters). */
        public double getHorizontalRange() {
            return horizontalRange;
        }

        /** @return The maximum vertical height from the ground (meters). */
        public double getMaxHeight() {
            return maxHeight;
        }
    }

    /**
     * Calculates projectile trajectory using standard Earth gravity.
     *
     * @param initialVelocity Initial speed of the projectile (m/s).
     * @param launchAngleDegrees Launch angle from the horizontal (degrees).
     * @param initialHeight Starting height of the projectile (m).
     * @return A {@link Result} object with the trajectory data.
     */
    public static Result calculateTrajectory(double initialVelocity, double launchAngleDegrees, double initialHeight) {
        return calculateTrajectory(initialVelocity, launchAngleDegrees, initialHeight, GRAVITY);
    }

    /**
     * Calculates projectile trajectory with a custom gravity value.
     *
     * @param initialVelocity Initial speed (m/s). Must be non-negative.
     * @param launchAngleDegrees Launch angle (degrees).
     * @param initialHeight Starting height (m). Must be non-negative.
     * @param gravity Acceleration due to gravity (m/s^2). Must be positive.
     * @return A {@link Result} object with the trajectory data.
     */
    public static Result calculateTrajectory(double initialVelocity, double launchAngleDegrees, double initialHeight, double gravity) {
        if (initialVelocity < 0 || initialHeight < 0 || gravity <= 0) {
            throw new IllegalArgumentException("Velocity, height, and gravity must be non-negative, and gravity must be positive.");
        }

        double launchAngleRadians = Math.toRadians(launchAngleDegrees);
        double initialVerticalVelocity = initialVelocity * Math.sin(launchAngleRadians); // Initial vertical velocity
        double initialHorizontalVelocity = initialVelocity * Math.cos(launchAngleRadians); // Initial horizontal velocity

        // Correctly calculate total time of flight using the quadratic formula for vertical motion.
        // y(t) = y0 + initialVerticalVelocity*t - 0.5*g*t^2. We solve for t when y(t) = 0.
        double totalTimeOfFlight = (initialVerticalVelocity + Math.sqrt(initialVerticalVelocity * initialVerticalVelocity + 2 * gravity * initialHeight)) / gravity;

        // Calculate max height. If launched downwards, max height is the initial height.
        double maxHeight;
        if (initialVerticalVelocity > 0) {
            double heightGained = initialVerticalVelocity * initialVerticalVelocity / (2 * gravity);
            maxHeight = initialHeight + heightGained;
        } else {
            maxHeight = initialHeight;
        }

        double horizontalRange = initialHorizontalVelocity * totalTimeOfFlight;

        return new Result(totalTimeOfFlight, horizontalRange, maxHeight);
    }
}

package com.thealgorithms.prefixsum;

/**
 * Implements the Difference Array algorithm.
 *
 * <p>
 * The Difference Array is an auxiliary data structure that enables efficient range update operations.
 * It is based on the mathematical concept of Finite Differences.
 * </p>
 *
 * <p>
 * <strong>Key Operations:</strong>
 * <ul>
 * <li>Range Update (Add value to [L, R]): O(1)</li>
 * <li>Reconstruction (Prefix Sum): O(N)</li>
 * </ul>
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Finite_difference">Finite Difference (Wikipedia)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Prefix_sum">Prefix Sum (Wikipedia)</a>
 * @author Chahat Sandhu, <a href="https://github.com/singhc7">singhc7</a>
 */
public class DifferenceArray {

    private final long[] differenceArray;
    private final int n;

    /**
     * Initializes the Difference Array from a given integer array.
     *
     * @param inputArray The initial array. Cannot be null or empty.
     * @throws IllegalArgumentException if the input array is null or empty.
     */
    public DifferenceArray(int[] inputArray) {
        if (inputArray == null || inputArray.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty.");
        }
        this.n = inputArray.length;
        // Size n + 1 allows for branchless updates at the right boundary (r + 1).
        this.differenceArray = new long[n + 1];
        initializeDifferenceArray(inputArray);
    }

    private void initializeDifferenceArray(int[] inputArray) {
        differenceArray[0] = inputArray[0];
        for (int i = 1; i < n; i++) {
            differenceArray[i] = inputArray[i] - inputArray[i - 1];
        }
    }

    /**
     * Adds a value to all elements in the range [l, r].
     *
     * <p>
     * This method uses a branchless approach by allocating an extra element at the end
     * of the array, avoiding the conditional check for the right boundary.
     * </p>
     *
     * @param l   The starting index (inclusive).
     * @param r   The ending index (inclusive).
     * @param val The value to add.
     * @throws IllegalArgumentException if the range is invalid.
     */
    public void update(int l, int r, int val) {
        if (l < 0 || r >= n || l > r) {
            throw new IllegalArgumentException(String.format("Invalid range: [%d, %d] for array of size %d", l, r, n));
        }

        differenceArray[l] += val;
        differenceArray[r + 1] -= val;
    }

    /**
     * Reconstructs the final array using prefix sums.
     *
     * @return The resulting array after all updates. Returns long[] to handle potential overflows.
     */
    public long[] getResultArray() {
        long[] result = new long[n];
        result[0] = differenceArray[0];

        for (int i = 1; i < n; i++) {
            result[i] = differenceArray[i] + result[i - 1];
        }
        return result;
    }
}

package com.thealgorithms.scheduling;

import java.util.Arrays;
import java.util.Comparator;

/**
 * The {@code HighestResponseRatioNextScheduling} class implements the
 * Highest Response Ratio Next (HRRN) scheduling algorithm.
 * HRRN is a non-preemptive scheduling algorithm that selects the process with
 * the highest response ratio for execution.
 * The response ratio is calculated as:
 *
 * <pre>
 *     Response Ratio = (waiting time + burst time) / burst time
 * </pre>
 *
 * HRRN is designed to reduce the average waiting time and improve overall
 * system performance by balancing between short and long processes,
 * minimizing process starvation.
 */
public final class HighestResponseRatioNextScheduling {

    private static final int PROCESS_NOT_FOUND = -1;
    private static final double INITIAL_MAX_RESPONSE_RATIO = -1.0;

    private HighestResponseRatioNextScheduling() {
    }

    /**
     * Represents a process in the scheduling algorithm.
     */
    private static class Process {
        String name;
        int arrivalTime;
        int burstTime;
        int turnAroundTime;
        boolean finished;

        Process(String name, int arrivalTime, int burstTime) {
            this.name = name;
            this.arrivalTime = arrivalTime;
            this.burstTime = burstTime;
            this.turnAroundTime = 0;
            this.finished = false;
        }

        /**
         * Calculates the response ratio for this process.
         *
         * @param currentTime The current time in the scheduling process.
         * @return The response ratio for this process.
         */
        double calculateResponseRatio(int currentTime) {
            return (double) (burstTime + currentTime - arrivalTime) / burstTime;
        }
    }

    /**
     * Calculates the Turn Around Time (TAT) for each process.
     *
     * <p>Turn Around Time is calculated as the total time a process spends
     * in the system from arrival to completion. It is the sum of the burst time
     * and the waiting time.</p>
     *
     * @param processNames Array of process names.
     * @param arrivalTimes Array of arrival times corresponding to each process.
     * @param burstTimes Array of burst times for each process.
     * @param noOfProcesses The number of processes.
     * @return An array of Turn Around Times for each process.
     */
    public static int[] calculateTurnAroundTime(final String[] processNames, final int[] arrivalTimes, final int[] burstTimes, final int noOfProcesses) {
        int currentTime = 0;
        int[] turnAroundTime = new int[noOfProcesses];
        Process[] processes = new Process[noOfProcesses];

        for (int i = 0; i < noOfProcesses; i++) {
            processes[i] = new Process(processNames[i], arrivalTimes[i], burstTimes[i]);
        }

        Arrays.sort(processes, Comparator.comparingInt(p -> p.arrivalTime));

        int finishedProcessCount = 0;
        while (finishedProcessCount < noOfProcesses) {
            int nextProcessIndex = findNextProcess(processes, currentTime);
            if (nextProcessIndex == PROCESS_NOT_FOUND) {
                currentTime++;
                continue;
            }

            Process currentProcess = processes[nextProcessIndex];
            currentTime = Math.max(currentTime, currentProcess.arrivalTime);
            currentProcess.turnAroundTime = currentTime + currentProcess.burstTime - currentProcess.arrivalTime;
            currentTime += currentProcess.burstTime;
            currentProcess.finished = true;
            finishedProcessCount++;
        }

        for (int i = 0; i < noOfProcesses; i++) {
            turnAroundTime[i] = processes[i].turnAroundTime;
        }

        return turnAroundTime;
    }

    /**
     * Calculates the Waiting Time (WT) for each process.
     *
     * @param turnAroundTime The Turn Around Times for each process.
     * @param burstTimes The burst times for each process.
     * @return An array of Waiting Times for each process.
     */
    public static int[] calculateWaitingTime(int[] turnAroundTime, int[] burstTimes) {
        int[] waitingTime = new int[turnAroundTime.length];
        for (int i = 0; i < turnAroundTime.length; i++) {
            waitingTime[i] = turnAroundTime[i] - burstTimes[i];
        }
        return waitingTime;
    }

    /**
     * Finds the next process to be scheduled based on arrival times and the current time.
     *
     * @param processes Array of Process objects.
     * @param currentTime The current time in the scheduling process.
     * @return The index of the next process to be scheduled, or PROCESS_NOT_FOUND if no process is ready.
     */
    private static int findNextProcess(Process[] processes, int currentTime) {
        return findHighestResponseRatio(processes, currentTime);
    }

    /**
     * Finds the process with the highest response ratio.
     *
     * <p>The response ratio is calculated as:
     * (waiting time + burst time) / burst time
     * where waiting time = current time - arrival time</p>
     *
     * @param processes Array of Process objects.
     * @param currentTime The current time in the scheduling process.
     * @return The index of the process with the highest response ratio, or PROCESS_NOT_FOUND if no process is ready.
     */
    private static int findHighestResponseRatio(Process[] processes, int currentTime) {
        double maxResponseRatio = INITIAL_MAX_RESPONSE_RATIO;
        int maxIndex = PROCESS_NOT_FOUND;

        for (int i = 0; i < processes.length; i++) {
            Process process = processes[i];
            if (!process.finished && process.arrivalTime <= currentTime) {
                double responseRatio = process.calculateResponseRatio(currentTime);
                if (responseRatio > maxResponseRatio) {
                    maxResponseRatio = responseRatio;
                    maxIndex = i;
                }
            }
        }
        return maxIndex;
    }
}

package com.thealgorithms.slidingwindow;

/**
 * The Sliding Window algorithm is used to find the maximum sum of a subarray
 * of a fixed size k within a given array.
 *
 * <p>
 * Worst-case performance O(n)
 * Best-case performance O(n)
 * Average performance O(n)
 * Worst-case space complexity O(1)
 *
 * @author Your Name (https://github.com/Chiefpatwal)
 */
public final class MaxSumKSizeSubarray {

    // Prevent instantiation
    private MaxSumKSizeSubarray() {
    }

    /**
     * This method finds the maximum sum of a subarray of a given size k.
     *
     * @param arr is the input array where the maximum sum needs to be found
     * @param k   is the size of the subarray
     * @return the maximum sum of the subarray of size k
     */
    public static int maxSumKSizeSubarray(int[] arr, int k) {
        if (arr.length < k) {
            return -1; // Edge case: not enough elements
        }

        int maxSum;
        int windowSum = 0;

        // Calculate the sum of the first window
        for (int i = 0; i < k; i++) {
            windowSum += arr[i];
        }
        maxSum = windowSum;

        // Slide the window across the array
        for (int i = k; i < arr.length; i++) {
            windowSum += arr[i] - arr[i - k];
            maxSum = Math.max(maxSum, windowSum);
        }

        return maxSum;
    }
}

package com.thealgorithms.sorts;

/**
 * The Dutch National Flag Sort sorts a sequence of values into three permutations which are defined
 * by a value given as the indented middle. First permutation: values less than middle. Second
 * permutation: values equal middle. Third permutation: values greater than middle. If no indented
 * middle is given, this implementation will use a value from the given Array. This value is the one
 * positioned in the arrays' middle if the arrays' length is odd. If the arrays' length is even, the
 * value left to the middle will be used. More information and Pseudocode:
 * https://en.wikipedia.org/wiki/Dutch_national_flag_problem
 */
public class DutchNationalFlagSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(T[] array) {
        return dutchNationalFlagSort(array, array[(int) Math.ceil((array.length) / 2.0) - 1]);
    }

    public <T extends Comparable<T>> T[] sort(T[] array, T intendedMiddle) {
        return dutchNationalFlagSort(array, intendedMiddle);
    }

    private <T extends Comparable<T>> T[] dutchNationalFlagSort(final T[] array, final T intendedMiddle) {
        int i = 0;
        int j = 0;
        int k = array.length - 1;

        while (j <= k) {
            if (SortUtils.less(array[j], intendedMiddle)) {
                SortUtils.swap(array, i, j);
                j++;
                i++;
            } else if (SortUtils.greater(array[j], intendedMiddle)) {
                SortUtils.swap(array, j, k);
                k--;
            } else {
                j++;
            }
        }
        return array;
    }
}

