        assert_eq!(log(E, E, 0.0), 1.0);
        assert_eq!(log(E, E.powi(100), 0.0), 100.0);
        assert_eq!(log(10, 10000.0, 0.0), 4.0);
        assert_eq!(log(234501.0, 1.0, 1.0), 0.0);
    }

    #[test]
