module test_math

import math

@[export: 'square']
fn calculate_square(i int) int {
	return i * i
}

@[export: 'sqrt_of_sum_of_squares']
fn calculate_sqrt_of_sum_of_squares(x f64, y f64) f64 {
	return math.sqrt(x * x + y * y)
}

// SSE Instruction Set
// SSE3: Added with later Pentium 4
// ADDSUBPD, ADDSUBPS, HADDPD, HADDPS, HSUBPD, HSUBPS, MOVDDUP, MOVSHDUP, MOVSLDUP
// The HADDPS instruction performs horizontal addition of two vectors of floats using SSE3
// instructions.

@[if amd64 && !tinyc && !msvc]
fn horizontal_add_sse3(a &f32, b &f32, result &f32) {
	unsafe {
		asm volatile amd64 {
			movaps xmm0, [a] // Load 4 floats from array a into SSE3 register xmm0
			movaps xmm1, [b] // Load 4 floats from array b into SSE3 register xmm1
			haddps xmm0, xmm1 // Perform horizontal add of xmm0 and xmm1
			movaps [result], xmm0 // Store the result back to memory
			; ; r (a)
			  r (b)
			  r (result)
			; xmm0
			  xmm1
		}
	}
}

fn main() {
	a := [f32(1.0), 2.0, 3.0, 4.0]
	b := [f32(5.0), 6.0, 7.0, 8.0]
	result := []f32{len: 4}
	horizontal_add_sse3(&a[0], &b[0], &result[0])
	println(result)
	// The result should be [3.0, 7.0, 11.0, 15.0] due to horizontal addition.
	// 1.0 + 2.0 = 3.0
	// 3.0 + 4.0 = 7.0
	// 5.0 + 6.0 = 11.0
	// 7.0 + 8.0 = 15.0
	assert result == [f32(3.0), 7.0, 11.0, 15.0]
}

module library

// add_1 is exported with the C name `add_1`.
// It can be called by external programs, when the module is compiled
// as a shared library.
// It is exported, because the function is declared as public with `pub`.
// The exported C name is `add_1`, because of the export: tag.
// (Normally, the exported name is a V mangled version based on the module
// name followed by __, followed by the fn name, i.e. it would have been
// `library__add_1`, if not for the export: tag).
@[export: 'add_1']
pub fn add_1(x int, y int) int {
	return my_private_function(x + y)
}

// this function is not exported and will not be visible to external programs.
fn my_private_function(x int) int {
	return 1 + x
}

// Function signatures can be declared as types:

type Filter = fn (string) string

// Functions can accept function types as arguments:

fn filter(s string, f Filter) string {
	return f(s)
}

// Declare a function with a matching signature:

fn uppercase(s string) string {
	return s.to_upper()
}

fn main() {
	// A function can be assigned to a matching type:

	my_filter := Filter(uppercase)

	// You don't strictly need the `Filter` cast - it's only used
	// here to illustrate how these types are compatible.

	// All of the following prints "HELLO WORLD":

	println(filter('Hello world', my_filter))
	println(filter('Hello world', uppercase))
	println(filter('Hello world', fn (s string) string {
		return s.to_upper()
	}))
}

