module main

import gg
import os.asset
import rand

const n = 4
const tile = 110
const gap = 10
const pad = 24
const head = 52
const r = f32(18)
const speed = f32(0.14)
const board_px = n * tile + (n - 1) * gap
const width = pad * 2 + board_px
const height = head + board_px + 62
const wcolor = gg.rgb(104, 93, 79)

@[heap]
struct Game {
mut:
	ctx   &gg.Context = unsafe { nil }
	board []int
	moves int
	won   bool
	anim  bool
	t     f32
	from  int = -1
	to    int = -1
	val   int
}

fn main() {
	mut g := &Game{}
	g.shuffle()
	g.ctx = gg.new_context(
		bg_color:     gg.rgb(247, 244, 235)
		width:        width
		height:       height
		sample_count: 4
		window_title: '15 Puzzle'
		user_data:    g
		frame_fn:     frame
		event_fn:     event
		font_path:    asset.get_path('../assets', 'fonts/Graduate-Regular.ttf')
	)
	g.ctx.run()
}

fn frame(mut g Game) {
	g.step()
	g.ctx.begin()
	g.header()
	g.board()
	g.ctx.end()
}

fn event(e &gg.Event, mut g Game) {
	if e.typ == .key_down {
		match e.key_code {
			.escape {
				g.ctx.quit()
			}
			.r {
				g.shuffle()
			}
			.up, .w {
				if !g.anim {
					g.slide(1, 0)
				}
			}
			.down, .s {
				if !g.anim {
					g.slide(-1, 0)
				}
			}
			.left, .a {
				if !g.anim {
					g.slide(0, 1)
				}
			}
			.right, .d {
				if !g.anim {
					g.slide(0, -1)
				}
			}
			else {}
		}

		return
	}
	if !g.anim && e.typ == .mouse_down && e.mouse_button == .left {
		if i := g.hit(int(e.mouse_x), int(e.mouse_y)) {
			g.move(i)
		}
	}
}

fn (mut g Game) header() {
	g.ctx.draw_text(width / 2, 16, if g.won {
		'Solved in ${g.moves} moves. Press R to reshuffle.'
	} else {
		'Moves: ${g.moves}'
	},
		size:  if g.won { 16 } else { 20 }
		bold:  true
		align: .center
		color: if g.won { wcolor } else { gg.rgb(48, 44, 37) }
	)
}

fn (mut g Game) board() {
	g.ctx.draw_rect_filled(pad - 8, head - 8, board_px + 16, board_px + 16, gg.rgb(218, 206, 188))
	for i, v in g.board {
		if g.anim && i == g.from {
			continue
		}
		x, y := xy(i)
		g.tile(x, y, v, v != 0 && v == i + 1)
	}
	if g.anim {
		x0, y0 := xy(g.from)
		x1, y1 := xy(g.to)
		g.tile(int(f32(x0) + f32(x1 - x0) * g.t), int(f32(y0) + f32(y1 - y0) * g.t), g.val, false)
	}
	g.ctx.draw_text(pad, head + board_px + 22,
		'Arrow keys / WASD or click a tile next to the empty space.',
		size:  16
		color: wcolor
	)
	g.ctx.draw_text(width / 2, height - 18, '[R] Shuffle  [Esc] Quit',
		size:           16
		bold:           true
		align:          .center
		vertical_align: .middle
		color:          wcolor
	)
}

fn (mut g Game) tile(x int, y int, v int, ok bool) {
	fill, border := if v == 0 {
		gg.rgb(238, 232, 220), gg.rgb(210, 202, 191)
	} else if ok {
		gg.rgb(214, 173, 108), gg.rgb(168, 121, 56)
	} else {
		gg.rgb(84, 110, 122), gg.rgb(48, 66, 74)
	}
	g.ctx.draw_rounded_rect_filled(x, y, tile, tile, r, fill)
	g.ctx.draw_rounded_rect_empty(x, y, tile, tile, r, border)
	if v != 0 {
		g.ctx.draw_text(x + tile / 2, y + tile / 2, v.str(),
			size:           42
			bold:           true
			align:          .center
			vertical_align: .middle
			color:          gg.white
		)
	}
}

fn (mut g Game) shuffle() {
	g.board = []int{len: n * n}
	for i in 0 .. g.board.len - 1 {
		g.board[i] = i + 1
	}
	for _ in 0 .. 300 {
		e := g.board.index(0)
		ns := neighbors(e)
		j := ns[rand.intn(ns.len) or { 0 }]
		g.board[e], g.board[j] = g.board[j], g.board[e]
	}
	if done(g.board) {
		g.board[g.board.len - 2], g.board[g.board.len - 3] = g.board[g.board.len - 3], g.board[g.board.len - 2]
	}
	g.moves, g.won, g.anim, g.t, g.from, g.to, g.val = 0, false, false, 0, -1, -1, 0
}

fn (mut g Game) slide(dr int, dc int) {
	e := g.board.index(0)
	row, col := e / n + dr, e % n + dc
	if row >= 0 && row < n && col >= 0 && col < n {
		g.move(row * n + col)
	}
}

fn (mut g Game) move(i int) bool {
	if g.won || g.anim || i < 0 || i >= g.board.len || g.board[i] == 0 {
		return false
	}
	e := g.board.index(0)
	dr, dc := i / n - e / n, i % n - e % n
	if !((dr == 0 && (dc == 1 || dc == -1)) || (dc == 0 && (dr == 1 || dr == -1))) {
		return false
	}
	g.anim, g.t, g.from, g.to, g.val = true, 0, i, e, g.board[i]
	return true
}

fn (mut g Game) step() {
	if !g.anim {
		return
	}
	g.t += speed
	if g.t < 1 {
		return
	}
	g.board[g.to], g.board[g.from] = g.val, 0
	g.moves++
	g.won = done(g.board)
	g.anim, g.t, g.from, g.to, g.val = false, 0, -1, -1, 0
}

fn (g &Game) hit(mx int, my int) ?int {
	if mx < pad || my < head || mx >= pad + board_px || my >= head + board_px {
		return none
	}
	x, y := mx - pad, my - head
	col, row := x / (tile + gap), y / (tile + gap)
	if x % (tile + gap) >= tile || y % (tile + gap) >= tile {
		return none
	}
	return row * n + col
}

fn neighbors(i int) []int {
	row, col := i / n, i % n
	mut ns := []int{}
	if row > 0 {
		ns << i - n
	}
	if row + 1 < n {
		ns << i + n
	}
	if col > 0 {
		ns << i - 1
	}
	if col + 1 < n {
		ns << i + 1
	}
	return ns
}

fn xy(i int) (int, int) {
	return pad + (i % n) * (tile + gap), head + (i / n) * (tile + gap)
}

fn done(b []int) bool {
	for i in 0 .. b.len - 1 {
		if b[i] != i + 1 {
			return false
		}
	}
	return b[b.len - 1] == 0
}

module main

import gg
import math

const win_width = 700
const win_height = 800
const bg_color = gg.white

// A transparent color is used to aid in verifying that
// rendering is precise on each of the arc types (e.g. no overlapping or double rendered slices)
const colour = gg.rgba(100, 100, 0, 100)

enum Selection {
	segs = 0
	len
}

struct App {
mut:
	gg    &gg.Context = unsafe { nil }
	mouse struct {
	mut:
		x f32
		y f32
	}

	sel  Selection
	segs int = 8
}

fn main() {
	mut app := &App{}
	app.gg = gg.new_context(
		width:         win_width
		height:        win_height
		create_window: true
		window_title:  'Arcs and Slices'
		user_data:     app
		bg_color:      bg_color
		frame_fn:      on_frame
		event_fn:      on_event
	)
	app.gg.run()
}

fn on_frame(mut app App) {
	app.gg.begin()

	start := math.tau * app.mouse.y / (win_width * app.gg.scale)
	end := math.tau * app.mouse.x / (win_width * app.gg.scale)

	segs := if app.sel == .segs { '[${app.segs}]' } else { '${app.segs}' }
	app.gg.draw_text_def(10, 10, 'Segments: ${segs}')
	app.gg.draw_text_def(250, 10, 'Drawing Angles (radians)')
	app.gg.draw_text_def(200, 26, 'Start: ${start}°')
	app.gg.draw_text_def(350, 26, 'End: ${end}°')
	mut x, mut y := 0, -80

	y += 150
	x = 20
	app.gg.draw_text_def(10, y + 40, 'slice')
	x += 150
	app.gg.draw_slice_empty(x, y + 60, 50, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=50 empty')
	x += 150
	app.gg.draw_slice_empty(x, y + 60, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=0 empty')
	x += 150
	app.gg.draw_slice_filled(x, y + 60, 50, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=50 filled')
	x += 150
	app.gg.draw_slice_filled(x, y + 60, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=0 filled')

	y += 150
	x = 20
	app.gg.draw_text_def(10, y + 40, 'arc_empty')
	x += 150
	app.gg.draw_arc_empty(x, y + 60, 30, 20, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[30,50]')
	x += 150
	app.gg.draw_arc_empty(x, y + 60, -10, 60, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[-10,50]')
	x += 150
	app.gg.draw_arc_empty(x, y + 60, 50, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[50,50]')
	x += 150
	app.gg.draw_arc_empty(x, y + 60, 0, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[0,0]')

	y += 150
	x = 20
	app.gg.draw_text_def(10, y + 40, 'arc_filled')
	x += 150
	app.gg.draw_arc_filled(x, y + 60, 30, 20, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[30,50]')
	x += 150
	app.gg.draw_arc_filled(x, y + 60, -10, 60, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[-10,50]')
	x += 150
	app.gg.draw_arc_filled(x, y + 60, 50, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[50,50]')
	x += 150
	app.gg.draw_arc_filled(x, y + 60, 0, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=[0,0]')

	y += 150
	x = 20
	app.gg.draw_text_def(10, y + 40, 'arc_line')
	x += 150
	app.gg.draw_arc_line(x, y + 60, 50, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=50')
	x += 150
	app.gg.draw_arc_line(x, y + 60, 0, start, end, app.segs, colour)
	app.gg.draw_text_def(x - 50, y + 120, 'r=0')

	y += 150
	app.gg.draw_text_def(10, y + 20, 'Use arrow keys to increase/decrease number of segments.')
	app.gg.draw_text_def(10, y + 36,
		'Use the mouse to adjust the start/end angles, in radians. Mouse position (0,0) is at the top-left of the window.')
	app.gg.draw_text_def(10, y + 52,
		'Note: because y=0 is at the top of the screen and not the bottom, angle=0 is at the bottom of an arc, not the top!')
	app.gg.draw_text_def(10, y + 68,
		'Compared to a graph, where y=0 is at the bottom, arcs therefore appear y-flipped.')

	app.gg.end()
}

fn on_event(e &gg.Event, mut app App) {
	match e.typ {
		.key_down {
			match e.key_code {
				.escape {
					app.gg.quit()
				}
				.up {
					app.sel = unsafe { Selection(math.max(0, int(app.sel) - 1)) }
				}
				.down {
					app.sel = unsafe { Selection(math.min(int(Selection.len) - 1, int(app.sel) + 1)) }
				}
				.left {
					match app.sel {
						.segs {
							app.segs = math.max(1, app.segs / 2)
						}
						else {}
					}
				}
				.right {
					match app.sel {
						.segs {
							app.segs = math.min(64, app.segs * 2)
						}
						else {}
					}
				}
				else {}
			}
		}
		.mouse_move {
			app.mouse.x = e.mouse_x
			app.mouse.y = e.mouse_y
		}
		else {}
	}
}

